#include <stdint.h>
#define KS_SEP_SPACE 0
#define KS_SEP_TAB 1
#define KS_SEP_LINE 2
#define KS_SEP_MAX 2

#define KSTREAM_SIZE 16384

typedef struct {
    int64_t n, m;
    uint8_t *s;
} kstring_t;

typedef struct {
    int fd;
    gzFile f;
    unsigned char *buf;
    int begin, end, is_eof;
    int bufsize;
} kstream_t;

#define ks_eof(ks) ((ks)->is_eof && (ks)->begin >= (ks)->end)
#define ks_rewind(ks) ((ks)->is_eof = (ks)->begin = (ks)->end = 0)

static inline kstream_t *ks_init(gzFile f) {
    kstream_t *ks = (kstream_t*)calloc(1, sizeof(kstream_t));
    ks->f = f;
    ks->bufsize = KSTREAM_SIZE;
    ks->buf = (unsigned char*)malloc(ks->bufsize);
    return ks;
}

static inline void ks_destroy(kstream_t *ks) {
    if (ks) { free(ks->buf); free(ks); }
}

static inline int ks_getc(kstream_t *ks) {
    if (ks->is_eof && ks->begin >= ks->end) return -1;
    if (ks->begin >= ks->end) {
        ks->begin = 0;
        ks->end = gzread(ks->f, ks->buf, ks->bufsize);
        if (ks->end == 0) { ks->is_eof = 1; return -1; }
    }
    return (int)ks->buf[ks->begin++];
}

static int ks_getuntil(kstream_t *ks, int delimiter, kstring_t *str, int *dret) {
    int gotany = 0;
    if (dret) *dret = 0;
    str->n = 0;
    for (;;) {
        int i;
        if (ks->begin >= ks->end) {
            if (!ks->is_eof) {
                ks->begin = 0;
                ks->end = gzread(ks->f, ks->buf, ks->bufsize);
                if (ks->end == 0) { ks->is_eof = 1; break; }
            } else break;
        }
        if (delimiter == KS_SEP_LINE) {
            for (i = ks->begin; i < ks->end; ++i)
                if (ks->buf[i] == '\n') break;
        } else if (delimiter > KS_SEP_MAX) {
            for (i = ks->begin; i < ks->end; ++i)
                if (ks->buf[i] == delimiter) break;
        } else if (delimiter == KS_SEP_SPACE) {
            for (i = ks->begin; i < ks->end; ++i)
                if (isspace(ks->buf[i])) break;
        } else {
            for (i = ks->begin; i < ks->end; ++i)
                if (isspace(ks->buf[i]) && ks->buf[i] != ' ') break;
        }
        if (str->m - str->n < (size_t)(i - ks->begin + 1)) {
            str->m = str->n + (i - ks->begin) + 1;
            str->m = str->m < 8 ? 8 : str->m;
            str->m = (str->m * 3) >> 1;
            str->s = (uint8_t*)realloc(str->s, str->m);
        }
        gotany = 1;
        memcpy(str->s + str->n, ks->buf + ks->begin, i - ks->begin);
        str->n += i - ks->begin;
        ks->begin = i + 1;
        if (i < ks->end) {
            if (dret) *dret = ks->buf[i];
            break;
        }
    }
    if (str->s == NULL) {
        str->m = 1;
        str->s = (uint8_t*)calloc(1, 1);
    } else if (!gotany) return -1;
    str->s[str->n] = '\0';
    return str->n;
}

typedef struct {
    kstring_t name, comment, seq, qual;
    int last_char;
    kstream_t *f;
} kseq_t;

static inline kseq_t *kseq_init(gzFile fd) {
    kseq_t *s = (kseq_t*)calloc(1, sizeof(kseq_t));
    s->f = ks_init(fd);
    return s;
}

static inline void kseq_destroy(kseq_t *ks) {
    if (!ks) return;
    free(ks->name.s); free(ks->comment.s);
    free(ks->seq.s); free(ks->qual.s);
    ks_destroy(ks->f);
    free(ks);
}

static int kseq_read(kseq_t *seq) {
    int c;
    kstream_t *ks = seq->f;
    if (seq->last_char == 0) {
        while ((c = ks_getc(ks)) != -1 && c != '>' && c != '@');
        if (c == -1) return -1;
        seq->last_char = c;
    }
    seq->comment.n = seq->seq.n = seq->qual.n = 0;
    if (ks_getuntil(ks, 0, &seq->name, &c) < 0) return -1;
    if (c != '\n') ks_getuntil(ks, KS_SEP_LINE, &seq->comment, 0);
    while ((c = ks_getc(ks)) != -1 && c != '>' && c != '+' && c != '@') {
        if (c == '\n') continue;
        if (seq->seq.n + 1 >= seq->seq.m) {
            seq->seq.m = seq->seq.m < 8 ? 16 : seq->seq.m * 2;
            seq->seq.s = (uint8_t*)realloc(seq->seq.s, seq->seq.m);
        }
        seq->seq.s[seq->seq.n++] = c;
        ks_getuntil(ks, KS_SEP_LINE, &seq->seq, 0);
    }
    if (seq->seq.n + 1 >= seq->seq.m) {
        seq->seq.m = seq->seq.n + 2;
        seq->seq.s = (uint8_t*)realloc(seq->seq.s, seq->seq.m);
    }
    seq->seq.s[seq->seq.n] = '\0';
    if (c == '>' || c == '@') { seq->last_char = c; return seq->seq.n; }
    if (c == '+') {
        seq->last_char = 0;
        if (seq->comment.n == 0 || (seq->qual.m < seq->seq.m)) {
            seq->qual.m = seq->seq.m;
            seq->qual.s = (uint8_t*)realloc(seq->qual.s, seq->qual.m);
        }
        while ((c = ks_getc(ks)) != -1 && c != '\n');
        while ((seq->qual.n < seq->seq.n) && (c = ks_getc(ks)) != -1) {
            if (c == '\n') continue;
            seq->qual.s[seq->qual.n++] = c;
            ks_getuntil(ks, KS_SEP_LINE, &seq->qual, 0);
        }
        seq->qual.s[seq->qual.n] = '\0';
    } else {
        seq->last_char = c;
    }
    return seq->seq.n;
}

