    free(h);
}

static int nhash_get(nhash_t *h, const char *name) {
    uint32_t k = hash_string(name) % NHASH;
    nentry_t *p = h->heads[k];
    while (p) {
        if (strcmp(p->name, name) == 0) return p->idx;
        p = p->next;
    }
    return -1;
}

static int nhash_insert(nhash_t *h, const char *name) {
    uint32_t k = hash_string(name) % NHASH;
    nentry_t *p = h->heads[k];
    while (p) {
        if (strcmp(p->name, name) == 0) return p->idx;
        p = p->next;
    }
    p = calloc(1, sizeof(nentry_t));
    p->name = strdup(name);
    p->idx = h->n++;
    p->next = h->heads[k];
    h->heads[k] = p;
    return p->idx;
