        long long nA=0, nC=0, nG=0, nT=0, n2ry=0, n2other=0, n3=0, nN=0;
        long long ncpg2=0;

        for (i = 0; i < (int)seq->seq.n; i++) {
            int ch = toupper((unsigned char)s[i]);
            switch (ch) {
                case 'A': nA++; prev_c_or_s = 0; break;
                case 'C': nC++; prev_c_or_s = 1; break;
                case 'G': 
                    nG++; 
                    if (prev_c_or_s == 1) ncpg2 += 2; /* CG dinucleotide */
                    prev_c_or_s = 2;
                    break;
                case 'T': nT++; prev_c_or_s = 0; break;
                case 'N': nN++; prev_c_or_s = 0; break;
                case 'R': n2ry++; prev_c_or_s = 0; break;
                case 'Y': n2ry++; prev_c_or_s = 0; break;
                case 'S': /* S = C or G (strong) */
                    if (prev_c_or_s == 1 || prev_c_or_s == 2) {
                        n2other++; /* adjacent to C or G -> col10 */
                    } else {
                        ncpg2++; /* isolated S -> col9 */
                    }
                    prev_c_or_s = 0; /* S doesn't continue CpG tracking */
                    /* Actually S counts as 2-base ambig */
                    /* need to increment 2-base count */
                    /* Let me fix this */
                    break;
                case 'W': n2other++; prev_c_or_s = 0; break;
                case 'M': n2other++; prev_c_or_s = 0; break;
                case 'K': n2other++; prev_c_or_s = 0; break;
                case 'H': n3++; prev_c_or_s = 0; break;
                case 'B': n3++; prev_c_or_s = 0; break;
                case 'V': n3++; prev_c_or_s = 0; break;
                case 'D': n3++; prev_c_or_s = 0; break;
                default: prev_c_or_s = 0; break;
            }
        }

        printf("%s\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t0\n",
               seq->name.s, total, nA, nC, nG, nT,
               n2ry + n2other, n3, nN, ncpg2, n2other, n2ry);
    }

    kseq_destroy(seq);
    gzclose(fp);
    return 0;
}

