/* Print sequence with line wrapping */
static void print_seq(FILE *out, const char *seq, int len, int line_len) {
    if (line_len <= 0 || line_len >= len) {
        fwrite(seq, 1, len, out);
        fputc('\n', out);
    } else {
        int i;
        for (i = 0; i < len; i += line_len) {
            int l = len - i < line_len ? len - i : line_len;
            fwrite(seq + i, 1, l, out);
            fputc('\n', out);
        }
    }
}

