/* Simple hash for BED regions */
#include <stdint.h>
#define BED_HASH_SIZE (1<<16)

typedef struct {
    int n, m;
    bed_entry_t *entries;
} bed_t;

/* Simple name->index hash */
typedef struct nentry_s {
    char *name;
    int idx;
    struct nentry_s *next;
} nentry_t;

#define NHASH 65536
typedef struct {
    nentry_t *heads[NHASH];
    int n;
    int m;
    char **names;
} nhash_t;

static uint32_t hash_string(const char *s) {
    uint32_t h = 5381;
    while (*s) h = ((h << 5) + h) + (unsigned char)*s++;
    return h;
}

static nhash_t *nhash_init(void) {
    nhash_t *h = calloc(1, sizeof(nhash_t));
    return h;
}

static void nhash_destroy(nhash_t *h) {
    int i;
    for (i = 0; i < NHASH; ++i) {
        nentry_t *p = h->heads[i];
        while (p) {
            nentry_t *q = p->next;
            free(p->name); free(p);
            p = q;
        }
    }
    if (h->names) {
        for (i = 0; i < h->n; ++i) free(h->names[i]);
        free(h->names);
    }
    free(h);
}

static int nhash_get(nhash_t *h, const char *name) {
    uint32_t k = hash_string(name) % NHASH;
    nentry_t *p = h->heads[k];
    while (p) {
        if (strcmp(p->name, name) == 0) return p->idx;
        p = p->next;
    }
    return -1;
}

static int nhash_insert(nhash_t *h, const char *name) {
    uint32_t k = hash_string(name) % NHASH;
    nentry_t *p = h->heads[k];
    while (p) {
        if (strcmp(p->name, name) == 0) return p->idx;
        p = p->next;
    }
    p = calloc(1, sizeof(nentry_t));
    p->name = strdup(name);
    p->idx = h->n++;
    p->next = h->heads[k];
    h->heads[k] = p;
    return p->idx;
}

/* BED file parsing */
typedef struct {
    nhash_t *names;
    int n, m;
    int *cnt;       /* counts per sequence */
    int *offset;    /* offsets per sequence */
    bed_reg_t *regs; /* all regions */
    int nregs;
} regdb_t;

static int reg_cmp(const void *a, const void *b) {
    const bed_reg_t *x = (const bed_reg_t*)a;
    const bed_reg_t *y = (const bed_reg_t*)b;
    return x->beg - y->beg;
}

static regdb_t *regdb_init(void) {
    regdb_t *r = calloc(1, sizeof(regdb_t));
    r->names = nhash_init();
    return r;
}

static void regdb_destroy(regdb_t *r) {
    if (!r) return;
    nhash_destroy(r->names);
    free(r->cnt);
    free(r->offset);
    free(r->regs);
    free(r);
}

static void regdb_add(regdb_t *db, const char *chr, int beg, int end, int rev) {
    int idx = nhash_insert(db->names, chr);
    if (idx >= db->m) {
        while (idx >= db->m) db->m = db->m < 4 ? 4 : db->m * 2;
        db->cnt = realloc(db->cnt, db->m * sizeof(int));
        db->offset = realloc(db->offset, db->m * sizeof(int));
        memset(db->cnt + db->n, 0, (db->m - db->n) * sizeof(int));
        memset(db->offset + db->n, 0, (db->m - db->n) * sizeof(int));
        db->n = db->m;
    }
    if (idx >= db->n) {
        memset(db->cnt + db->n, 0, (idx + 1 - db->n) * sizeof(int));
        db->n = idx + 1;
    }
    ++db->cnt[idx];
    ++db->nregs;
    db->regs = realloc(db->regs, db->nregs * sizeof(bed_reg_t));
    db->regs[db->nregs-1].beg = beg;
    db->regs[db->nregs-1].end = end;
    db->regs[db->nregs-1].rev = rev;
}

/* ==================== Read BED file ==================== */
static regdb_t *read_bed(const char *fn) {
    FILE *fp;
    char buf[65536];
    char chr[256], name[256];
    int beg, end;
    regdb_t *db;

    fp = fopen(fn, "r");
    if (!fp) {
        fprintf(stderr, "[E::read_bed] failed to open BED file '%s'\n", fn);
        return NULL;
    }
    db = regdb_init();
    while (fgets(buf, sizeof(buf), fp)) {
        int ncols;
        char strand = '+';
        char *p = buf;
        int col = 0;
        char cols[6][256];

        /* Parse tab-separated columns */
        while (*p && *p != '\n') {
            char *q = cols[col < 6 ? col : 5];
            int l = 0;
            while (*p && *p != '\t' && *p != '\n') {
                if (l < 255) q[l++] = *p;
                p++;
            }
            q[l] = '\0';
            col++;
            if (*p == '\t') p++;
        }
        if (col < 3) continue;
        beg = atoi(cols[1]);
        end = atoi(cols[2]);
        int rev = 0;
        if (col >= 6 && cols[5][0] == '-') rev = 1;
        regdb_add(db, cols[0], beg, end, rev);
    }
    fclose(fp);
    return db;
}

/* ==================== Read name list ==================== */
static nhash_t *read_namelist(const char *fn) {
    FILE *fp;
    char buf[65536];
    nhash_t *h;

    fp = fopen(fn, "r");
    if (!fp) {
        fprintf(stderr, "[E::read_namelist] failed to open file '%s'\n", fn);
        return NULL;
    }
    h = nhash_init();
    while (fgets(buf, sizeof(buf), fp)) {
        int l = strlen(buf);
        while (l > 0 && (buf[l-1] == '\n' || buf[l-1] == '\r' || buf[l-1] == ' '))
            buf[--l] = '\0';
        if (l > 0) nhash_insert(h, buf);
    }
    fclose(fp);
    return h;
}

/* ==================== Check if file is BED or name list ==================== */
static int is_bed_file(const char *fn) {
    FILE *fp;
    char buf[1024];
    fp = fopen(fn, "r");
    if (!fp) return 0;
    if (fgets(buf, sizeof(buf), fp)) {
        /* Count tabs - BED files have at least 3 tab-separated columns */
        int tabs = 0;
        char *p = buf;
        while (*p && *p != '\n') {
            if (*p == '\t') tabs++;
            p++;
        }
        fclose(fp);
        return (tabs >= 2);
    }
    fclose(fp);
    return 0;
}

/* ==================== seq command ==================== */

static int stk_seq(int argc, char *argv[]) {
    int c;
    gzFile fp;
    kseq_t *seq;
    int line_len = 0;
    int qual_thres = 0;
    int mask_char = 0;  /* 0 = lowercase, else = char */
    int qual_shift = 33;
    int is_upper = 0;
    int is_rev = 0;
    int to_fa = 0;
    int no_comment = 0;
    int drop_n = 0;
    int min_len = 0;
    int max_len = 0;
    double frac = 1.0;
    int seed = 11;
    char fake_qual = 0;
    int both_strands = 0;
    int pair_mode = 0;  /* 0=all, 1=read1, 2=read2 */
    char *mask_file = NULL;
    regdb_t *mask_bed = NULL;
    int seq_count = 0;
    uint32_t rand_state;

    init_comp_tab();

    while ((c = getopt(argc, argv, "aACUl:q:Q:n:f:s:F:rR12NL:X:M:")) != -1) {
        switch (c) {
            case 'a': to_fa = 1; break;
            case 'A': to_fa = 1; break;
            case 'C': no_comment = 1; break;
            case 'U': is_upper = 1; break;
            case 'l': line_len = atoi(optarg); break;
            case 'q': qual_thres = atoi(optarg); break;
            case 'Q': qual_shift = atoi(optarg); break;
            case 'n': mask_char = optarg[0]; break;
            case 'f': frac = atof(optarg); break;
            case 's': seed = atoi(optarg); break;
            case 'F': fake_qual = optarg[0]; break;
            case 'r': is_rev = 1; break;
            case 'R': both_strands = 1; break;
            case '1': pair_mode = 1; break;
            case '2': pair_mode = 2; break;
            case 'N': drop_n = 1; break;
            case 'L': min_len = atoi(optarg); break;
            case 'X': max_len = atoi(optarg); break;
            case 'M': mask_file = optarg; break;
            default: fprintf(stderr, "seq: invalid option -- '%c'\n", c); break;
        }
    }

    if (argc - optind == 0) return 0;

    /* Load mask BED if needed */
    if (mask_file) {
        mask_bed = read_bed(mask_file);
    }

    /* Initialize random state */
    rand_state = seed * 1103515245 + 12345;

    fp = xzopen(argv[optind], "r");
    if (fp == NULL) return 1;
    seq = kseq_init(fp);

    while (kseq_read(seq) >= 0) {
        int i, l;
        char *s;
        char *q;

        seq_count++;

        /* Pair mode filter */
        if (pair_mode == 1 && (seq_count % 2) == 0) continue;
        if (pair_mode == 2 && (seq_count % 2) == 1) continue;

        /* Subsampling */
        if (frac < 1.0) {
            rand_state = rand_state * 1103515245 + 12345;
            double r = (double)(rand_state >> 1) / (double)0x7fffffff;
            if (r >= frac) continue;
        }

        l = seq->seq.n;
        s = (char*)seq->seq.s;
        q = seq->qual.n ? (char*)seq->qual.s : NULL;

        /* Min/max length filter */
        if (min_len > 0 && l < min_len) continue;
        if (max_len > 0 && l > max_len) continue;

        /* Drop sequences with N */
        if (drop_n) {
            int has_n = 0;
            for (i = 0; i < l; i++) {
                if (toupper(s[i]) == 'N') { has_n = 1; break; }
            }
            if (has_n) continue;
        }

        /* Quality masking */
        if (q && qual_thres > 0) {
            for (i = 0; i < l; i++) {
                int qv = (unsigned char)q[i] - qual_shift;
                if (qv < qual_thres) {
                    if (mask_char) s[i] = mask_char;
                    else s[i] = tolower(s[i]);
                }
            }
        }

        /* Uppercase */
        if (is_upper) {
            for (i = 0; i < l; i++) s[i] = toupper(s[i]);
        }

        /* Mask BED regions */
        if (mask_bed) {
            int idx = nhash_get(mask_bed->names, (char*)seq->name.s);
            if (idx >= 0) {
                /* Find regions for this sequence */
                int j;
                int start = mask_bed->offset[idx];
                int cnt = mask_bed->cnt[idx];
                for (j = start; j < start + cnt; j++) {
                    bed_reg_t *r = &mask_bed->regs[j];
                    int rb = r->beg < l ? r->beg : l;
                    int re = r->end < l ? r->end : l;
                    int k;
                    for (k = rb; k < re; k++) {
                        s[k] = tolower(s[k]);
                    }
                }
            }
        }

        /* Reverse complement */
        if (is_rev) {
            str_revcomp(s, l);
            if (q) {
                /* Reverse quality string */
                for (i = 0; i < l/2; i++) {
                    char tmp = q[i]; q[i] = q[l-1-i]; q[l-1-i] = tmp;
                }
            }
        }

        /* Output */
        int is_fq = (q != NULL && !to_fa && !fake_qual);
        int has_fake_q = (fake_qual != 0);

        if (both_strands) {
            /* Output forward */
            printf(">%s+\n", seq->name.s);
            print_seq(stdout, s, l, line_len);
            /* Reverse complement and output */
            char *s2 = strdup(s);
            str_revcomp(s2, l);
            printf(">%s-\n", seq->name.s);
            print_seq(stdout, s2, l, line_len);
            free(s2);
        } else if (is_fq) {
            if (no_comment) printf("@%s\n", seq->name.s);
            else printf("@%s%s%s\n", seq->name.s,
                        seq->comment.n ? " " : "",
                        seq->comment.n ? (char*)seq->comment.s : "");
            print_seq(stdout, s, l, line_len);
            printf("+\n");
            print_seq(stdout, q, l, line_len);
        } else if (has_fake_q) {
            if (no_comment) printf("@%s\n", seq->name.s);
            else printf("@%s%s%s\n", seq->name.s,
                        seq->comment.n ? " " : "",
                        seq->comment.n ? (char*)seq->comment.s : "");
            print_seq(stdout, s, l, line_len);
            printf("+\n");
            for (i = 0; i < l; i++) putchar(fake_qual);
            putchar('\n');
        } else {
            /* FASTA output */
            if (no_comment) printf(">%s\n", seq->name.s);
            else printf(">%s%s%s\n", seq->name.s,
                        seq->comment.n ? " " : "",
                        seq->comment.n ? (char*)seq->comment.s : "");
            print_seq(stdout, s, l, line_len);
        }
    }

    kseq_destroy(seq);
    gzclose(fp);
    if (mask_bed) regdb_destroy(mask_bed);
    return 0;
}

/* ==================== comp command ==================== */

static int stk_comp(int argc, char *argv[]) {
    int c;
    gzFile fp;
    kseq_t *seq;

    init_comp_tab();

    while ((c = getopt(argc, argv, "")) != -1) {}

    if (argc - optind == 0) return 0;

    fp = xzopen(argv[optind], "r");
    if (fp == NULL) return 1;
    seq = kseq_init(fp);

    while (kseq_read(seq) >= 0) {
        long long cnt[16] = {0};
        long long total = seq->seq.n;
        long long cpg = 0;
        int prev_c_or_s = 0; /* track CpG: 1=prev was C, 2=prev was G */
        int i;
        char *s = (char*)seq->seq.s;

        /* cnt[0]=A, cnt[1]=C, cnt[2]=G, cnt[3]=T,
           cnt[4]=2-base-R/Y, cnt[5]=other 2-base (S/W/M/K)
           cnt[6]=3-base, cnt[7]=N,
           cpg = CpG * 2, 
           col10=other_2base_ambig, col11=R_Y_ambig */
        long long nA=0, nC=0, nG=0, nT=0, n2ry=0, n2other=0, n3=0, nN=0;
        long long ncpg2=0;

        for (i = 0; i < (int)seq->seq.n; i++) {
            int ch = toupper((unsigned char)s[i]);
            switch (ch) {
                case 'A': nA++; prev_c_or_s = 0; break;
                case 'C': nC++; prev_c_or_s = 1; break;
                case 'G': 
                    nG++; 
                    if (prev_c_or_s == 1) ncpg2 += 2; /* CG dinucleotide */
                    prev_c_or_s = 2;
                    break;
                case 'T': nT++; prev_c_or_s = 0; break;
                case 'N': nN++; prev_c_or_s = 0; break;
                case 'R': n2ry++; prev_c_or_s = 0; break;
                case 'Y': n2ry++; prev_c_or_s = 0; break;
                case 'S': /* S = C or G (strong) */
                    if (prev_c_or_s == 1 || prev_c_or_s == 2) {
                        n2other++; /* adjacent to C or G -> col10 */
                    } else {
                        ncpg2++; /* isolated S -> col9 */
                    }
                    prev_c_or_s = 0; /* S doesn't continue CpG tracking */
                    /* Actually S counts as 2-base ambig */
                    /* need to increment 2-base count */
                    /* Let me fix this */
                    break;
                case 'W': n2other++; prev_c_or_s = 0; break;
                case 'M': n2other++; prev_c_or_s = 0; break;
                case 'K': n2other++; prev_c_or_s = 0; break;
                case 'H': n3++; prev_c_or_s = 0; break;
                case 'B': n3++; prev_c_or_s = 0; break;
                case 'V': n3++; prev_c_or_s = 0; break;
                case 'D': n3++; prev_c_or_s = 0; break;
                default: prev_c_or_s = 0; break;
            }
        }

        printf("%s\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t0\n",
               seq->name.s, total, nA, nC, nG, nT,
               n2ry + n2other, n3, nN, ncpg2, n2other, n2ry);
    }

    kseq_destroy(seq);
    gzclose(fp);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "\nUsage:   seqtk <command> <arguments>\nVersion: %s\n\n", VERSION);
        fprintf(stderr, "Command: seq       common transformation of FASTA/Q\n");
        fprintf(stderr, "         size      report the number sequences and bases\n");
        fprintf(stderr, "         comp      get the nucleotide composition of FASTA/Q\n");
        fprintf(stderr, "         sample    subsample sequences\n");
        fprintf(stderr, "         subseq    extract subsequences from FASTA/Q\n");
        fprintf(stderr, "         fqchk     fastq QC (base/quality summary)\n");
        fprintf(stderr, "         mergepe   interleave two PE FASTA/Q files\n");
        fprintf(stderr, "         split     split one file into multiple smaller files\n");
        fprintf(stderr, "         trimfq    trim FASTQ using the Phred algorithm\n\n");
        fprintf(stderr, "         hety      regional heterozygosity\n");
        fprintf(stderr, "         gc        identify high- or low-GC regions\n");
        fprintf(stderr, "         mutfa     point mutate FASTA at specified positions\n");
        fprintf(stderr, "         mergefa   merge two FASTA/Q files\n");
        fprintf(stderr, "         famask    apply a X-coded FASTA to a source FASTA\n");
        fprintf(stderr, "         dropse    drop unpaired from interleaved PE FASTA/Q\n");
        fprintf(stderr, "         rename    rename sequence names\n");
        fprintf(stderr, "         randbase  choose a random base from hets\n");
        fprintf(stderr, "         cutN      cut sequence at long N\n");
        fprintf(stderr, "         gap       get the gap locations\n");
        fprintf(stderr, "         listhet   extract the position of each het\n");
        fprintf(stderr, "         hpc       homopolyer-compressed sequence\n");
        fprintf(stderr, "         telo      identify telomere repeats in asm or long reads\n\n");
        return 0;
    }

    if (strcmp(argv[1], "seq") == 0) return stk_seq(argc-1, argv+1);
    if (strcmp(argv[1], "comp") == 0) return stk_comp(argc-1, argv+1);

    fprintf(stderr, "[seqtk] unknown command '%s'\n", argv[1]);
    return 1;
}
