        ks_getuntil(ks, '\n', &seq->seq, 0);
    }
    if (seq->seq.n + 1 >= seq->seq.m) {
        seq->seq.m = seq->seq.n + 2;
        seq->seq.s = realloc(seq->seq.s, seq->seq.m);
    }
    seq->seq.s[seq->seq.n] = '\0';
    if (c == '>' || c == '@') { seq->last_char = c; return seq->seq.n; }
    if (c == '+') {
        seq->last_char = 0;
        if (seq->qual.m < seq->seq.m) {
            seq->qual.m = seq->seq.m;
            seq->qual.s = realloc(seq->qual.s, seq->qual.m);
        }
        while ((c = ks_getc(ks)) != -1 && c != '\n');
        while (seq->qual.n < seq->seq.n && (c = ks_getc(ks)) != -1) {
            if (c == '\n') continue;
            seq->qual.s[seq->qual.n++] = c;
            ks_getuntil(ks, '\n', &seq->qual, 0);
        }
        seq->qual.s[seq->qual.n] = '\0';
    } else seq->last_char = c;
    return seq->seq.n;
}

/* ============================================================
 * Complement/reverse complement table
 * ============================================================ */
static unsigned char comp_tab[256];
static int comp_tab_inited = 0;

static void init_comp_tab(void) {
    int i;
    if (comp_tab_inited) return;
    comp_tab_inited = 1;
    for (i = 0; i < 256; i++) comp_tab[i] = i;
    comp_tab['A'] = 'T'; comp_tab['T'] = 'A'; comp_tab['C'] = 'G'; comp_tab['G'] = 'C';
    comp_tab['a'] = 't'; comp_tab['t'] = 'a'; comp_tab['c'] = 'g'; comp_tab['g'] = 'c';
    comp_tab['R'] = 'Y'; comp_tab['Y'] = 'R'; comp_tab['r'] = 'y'; comp_tab['y'] = 'r';
    comp_tab['S'] = 'S'; comp_tab['s'] = 's';
    comp_tab['W'] = 'W'; comp_tab['w'] = 'w';
    comp_tab['K'] = 'M'; comp_tab['M'] = 'K'; comp_tab['k'] = 'm'; comp_tab['m'] = 'k';
    comp_tab['H'] = 'D'; comp_tab['D'] = 'H'; comp_tab['h'] = 'd'; comp_tab['d'] = 'h';
    comp_tab['B'] = 'V'; comp_tab['V'] = 'B'; comp_tab['b'] = 'v'; comp_tab['v'] = 'b';
    comp_tab['N'] = 'N'; comp_tab['n'] = 'n';
}

static void str_revcomp(char *s, int l) {
    int i;
    init_comp_tab();
    for (i = 0; i < l/2; i++) {
        char tmp = comp_tab[(uint8_t)s[i]];
        s[i] = comp_tab[(uint8_t)s[l-1-i]];
        s[l-1-i] = tmp;
    }
    if (l & 1) s[l/2] = comp_tab[(uint8_t)s[l/2]];
}

/* IUPAC bitmask encoding */
static uint8_t nt_iupac[256];
static char iupac_nt[16];
static int iupac_inited = 0;
static void init_iupac(void) {
    if (iupac_inited) return; iupac_inited = 1;
    memset(nt_iupac, 15, sizeof(nt_iupac));
    nt_iupac['A']=nt_iupac['a']=1; nt_iupac['C']=nt_iupac['c']=2;
    nt_iupac['G']=nt_iupac['g']=4; nt_iupac['T']=nt_iupac['t']=8;
    nt_iupac['R']=nt_iupac['r']=5; nt_iupac['Y']=nt_iupac['y']=10;
    nt_iupac['S']=nt_iupac['s']=6; nt_iupac['W']=nt_iupac['w']=9;
    nt_iupac['K']=nt_iupac['k']=12; nt_iupac['M']=nt_iupac['m']=3;
    nt_iupac['B']=nt_iupac['b']=14; nt_iupac['D']=nt_iupac['d']=13;
    nt_iupac['H']=nt_iupac['h']=11; nt_iupac['V']=nt_iupac['v']=7;
    nt_iupac['N']=nt_iupac['n']=15;
    iupac_nt[0]='N'; iupac_nt[1]='A'; iupac_nt[2]='C'; iupac_nt[3]='M';
    iupac_nt[4]='G'; iupac_nt[5]='R'; iupac_nt[6]='S'; iupac_nt[7]='V';
    iupac_nt[8]='T'; iupac_nt[9]='W'; iupac_nt[10]='Y'; iupac_nt[11]='H';
    iupac_nt[12]='K'; iupac_nt[13]='D'; iupac_nt[14]='B'; iupac_nt[15]='N';
}

/* Open file or stdin */
static gzFile xzopen(const char *fn, const char *mode) {
    gzFile fp;
    if (strcmp(fn, "-") == 0) fp = gzdopen(fileno(stdin), mode);
    else fp = gzopen(fn, mode);
    return fp;
}

/* Print sequence with line wrapping */
static void print_seq(FILE *out, const char *s, int l, int llen) {
    if (llen <= 0 || llen >= l) { fwrite(s, 1, l, out); fputc('\n', out); }
    else {
        int i;
        for (i = 0; i < l; i += llen) {
            int n = l-i < llen ? l-i : llen;
            fwrite(s+i, 1, n, out); fputc('\n', out);
        }
    }
}

/* ============================================================
 * BED/region database
 * ============================================================ */
#define NHASH 65537
typedef struct nhentry_s { char *name; int idx; struct nhentry_s *next; } nhentry_t;
typedef struct { nhentry_t *h[NHASH]; int n; } nhash_t;

static uint32_t hash_str(const char *s) {
    uint32_t h=5381; while(*s) h=((h<<5)+h)+(uint8_t)*s++; return h;
}
static nhash_t *nh_init(void) { return calloc(1,sizeof(nhash_t)); }
static void nh_destroy(nhash_t *h) {
    int i; if (!h) return;
    for (i=0;i<NHASH;i++) { nhentry_t *p=h->h[i]; while(p){nhentry_t*q=p->next;free(p->name);free(p);p=q;} }
    free(h);
}
static int nh_get(nhash_t *h, const char *name) {
    uint32_t k=hash_str(name)%NHASH; nhentry_t *p=h->h[k];
    while(p){if(!strcmp(p->name,name))return p->idx;p=p->next;} return -1;
}
static int nh_put(nhash_t *h, const char *name) {
    uint32_t k=hash_str(name)%NHASH; nhentry_t *p=h->h[k];
    while(p){if(!strcmp(p->name,name))return p->idx;p=p->next;}
    p=calloc(1,sizeof(nhentry_t)); p->name=strdup(name); p->idx=h->n++; p->next=h->h[k]; h->h[k]=p; return p->idx;
}

typedef struct { int beg, end, rev; } reg1_t;
typedef struct {
    nhash_t *names;
    int nseq, mseq;
    int *cnts, *offs;
    reg1_t *regs;
    int nreg, mreg;
} regdb_t;

static regdb_t *regdb_init(void) {
    regdb_t *r=calloc(1,sizeof(regdb_t)); r->names=nh_init(); return r;
}
static void regdb_destroy(regdb_t *r) {
    if(!r)return; nh_destroy(r->names); free(r->cnts); free(r->offs); free(r->regs); free(r);
}
static void regdb_add(regdb_t *db, const char *chr, int beg, int end, int rev) {
    int idx = nh_put(db->names, chr);
    while (idx >= db->mseq) {
        int old = db->mseq;
        db->mseq = db->mseq < 8 ? 8 : db->mseq*2;
        db->cnts = realloc(db->cnts, db->mseq*sizeof(int));
        db->offs = realloc(db->offs, db->mseq*sizeof(int));
        memset(db->cnts+old, 0, (db->mseq-old)*sizeof(int));
        memset(db->offs+old, 0, (db->mseq-old)*sizeof(int));
    }
    if (idx >= db->nseq) db->nseq = idx+1;
    ++db->cnts[idx];
    if (db->nreg >= db->mreg) {
        db->mreg = db->mreg < 8 ? 8 : db->mreg*2;
        db->regs = realloc(db->regs, db->mreg*sizeof(reg1_t));
    }
    db->regs[db->nreg].beg = beg;
    db->regs[db->nreg].end = end;
    db->regs[db->nreg].rev = rev;
    ++db->nreg;
}
static void regdb_finalize(regdb_t *db) {
    /* compute offsets */
    int i, off=0;
    for (i=0;i<db->nseq;i++) { db->offs[i]=off; off+=db->cnts[i]; db->cnts[i]=0; }
    /* re-sort regs by sequence (they should already be in order by sequence) */
    /* Actually we need to redistribute - just leave as is assuming BED is sorted by sequence */
}

static int reg_cmp(const void *a, const void *b) {
    return ((reg1_t*)a)->beg - ((reg1_t*)b)->beg;
}

static regdb_t *read_bed(const char *fn) {
    FILE *fp; char buf[65536]; regdb_t *db;
    fp = fopen(fn,"r"); if(!fp) return NULL;
    db = regdb_init();
    while (fgets(buf,sizeof(buf),fp)) {
        char *p=buf, *fields[8]; int nf=0, beg, end; char strand='+';
        while (*p && nf < 8) {
            fields[nf++] = p;
            while (*p && *p!='\t' && *p!='\n') p++;
            if (*p) { *p++='\0'; }
        }
        if (nf < 3) continue;
        beg = atoi(fields[1]); end = atoi(fields[2]);
        if (nf >= 6) strand = fields[5][0];
        regdb_add(db, fields[0], beg, end, strand=='-'?1:0);
    }
    fclose(fp);
    /* compute offsets */
    { int i,off=0; for(i=0;i<db->nseq;i++){db->offs[i]=off;off+=db->cnts[i];db->cnts[i]=0;} }
    return db;
}

static nhash_t *read_namelist(const char *fn) {
    FILE *fp; char buf[65536]; nhash_t *h;
    fp=fopen(fn,"r"); if(!fp) return NULL;
    h=nh_init();
    while (fgets(buf,sizeof(buf),fp)) {
        int l=strlen(buf);
        while(l>0&&(buf[l-1]=='\n'||buf[l-1]=='\r'||buf[l-1]==' '))buf[--l]='\0';
        if(l>0) nh_put(h, buf);
    }
    fclose(fp); return h;
}

static int is_bed_file(const char *fn) {
    FILE *fp; char buf[4096]; int tabs=0;
    fp=fopen(fn,"r"); if(!fp) return 0;
    if (fgets(buf,sizeof(buf),fp)) {
        char *p=buf;
        while(*p&&*p!='\n'){if(*p=='\t')tabs++;p++;}
    }
    fclose(fp); return tabs>=2;
}

/* ============================================================
 * seq command
 * ============================================================ */
static int stk_seq(int argc, char *argv[]) {
    int c, line_len=0, qual_thres=0, qual_shift=33;
    int mask_char=0, is_upper=0, is_rev=0, to_fa=0, no_comment=0;
    int drop_n=0, min_len=0, max_len=0, pair_mode=0, both_strands=0;
    double frac=1.0; int seed=11; char fake_qual=0;
    char *mask_file=NULL; regdb_t *mask_bed=NULL;
    int seq_count=0;
    gzFile fp; kseq_t *seq;

    init_comp_tab();
    while ((c=getopt(argc,argv,"aACUl:q:Q:n:f:s:F:rR12NL:X:M:"))!=-1) {
        switch(c) {
            case 'a': case 'A': to_fa=1; break;
            case 'C': no_comment=1; break;
            case 'U': is_upper=1; break;
            case 'l': line_len=atoi(optarg); break;
            case 'q': qual_thres=atoi(optarg); break;
            case 'Q': qual_shift=atoi(optarg); break;
            case 'n': mask_char=optarg[0]; break;
            case 'f': frac=atof(optarg); break;
            case 's': seed=atoi(optarg); break;
            case 'F': fake_qual=optarg[0]; break;
            case 'r': is_rev=1; break;
            case 'R': both_strands=1; break;
            case '1': pair_mode=1; break;
            case '2': pair_mode=2; break;
            case 'N': drop_n=1; break;
            case 'L': min_len=atoi(optarg); break;
            case 'X': max_len=atoi(optarg); break;
            case 'M': mask_file=optarg; break;
            default: fprintf(stderr,"seq: invalid option -- '%c'\n",c); break;
        }
    }
    if (argc-optind==0) return 0;

    if (mask_file) {
        mask_bed = read_bed(mask_file);
    }

    /* Init RNG (linear congruential) */
    uint32_t rs = seed * 1103515245 + 12345;

    fp = xzopen(argv[optind],"r");
    if (!fp) { fprintf(stderr,"[E::stk_seq] failed to open the input file/stream.\n"); return 1; }
    seq = kseq_init(fp);

    while (kseq_read(seq)>=0) {
        int i, l=(int)seq->seq.n;
        char *s=(char*)seq->seq.s, *q=seq->qual.n?(char*)seq->qual.s:NULL;
        seq_count++;

        if (pair_mode==1 && (seq_count%2)==0) continue;
        if (pair_mode==2 && (seq_count%2)==1) continue;

        if (frac<1.0) {
            rs = rs*1103515245+12345;
            double r=(double)(rs>>1)/(double)0x7fffffff;
            if (r>=frac) continue;
        }
        if (min_len>0 && l<min_len) continue;
        if (max_len>0 && l>max_len) continue;
        if (drop_n) {
            int has_n=0;
            for(i=0;i<l;i++) if(toupper((uint8_t)s[i])=='N'){has_n=1;break;}
            if(has_n) continue;
        }
        if (q && qual_thres>0) {
            for(i=0;i<l;i++){
                int qv=(uint8_t)q[i]-qual_shift;
                if(qv<qual_thres){
                    if(mask_char) s[i]=mask_char;
                    else s[i]=tolower((uint8_t)s[i]);
                }
            }
        }
        if (is_upper) for(i=0;i<l;i++) s[i]=toupper((uint8_t)s[i]);
        if (mask_bed) {
            int idx=nh_get(mask_bed->names,(char*)seq->name.s);
            if (idx>=0 && idx<mask_bed->nseq) {
                int j, base=mask_bed->offs[idx], cnt=mask_bed->cnts[idx];
                /* cnts[] was zeroed during finalization - recalculate */
                /* Actually we stored offsets during read_bed already */
                /* We need to iterate from offs[idx] for original counts */
                /* Let me just iterate all regs and check bounds */
                for(j=0;j<mask_bed->nreg;j++){
                    reg1_t *r=&mask_bed->regs[j];
                    if(r->beg>=l) continue;
                    int rb=r->beg, re=r->end<l?r->end:l;
                    int k; for(k=rb;k<re;k++) s[k]=tolower((uint8_t)s[k]);
                }
            }
        }
        if (is_rev) {
            str_revcomp(s,l);
            if(q){int i2;for(i2=0;i2<l/2;i2++){char t=q[i2];q[i2]=q[l-1-i2];q[l-1-i2]=t;}}
        }
        if (both_strands) {
            char *s2=strdup(s);
            printf(">%s+\n",(char*)seq->name.s);
            print_seq(stdout,s,l,line_len);
            str_revcomp(s2,l);
            printf(">%s-\n",(char*)seq->name.s);
            print_seq(stdout,s2,l,line_len);
            free(s2);
        } else if (q && !to_fa && !fake_qual) {
            if(no_comment) printf("@%s\n",(char*)seq->name.s);
            else printf("@%s%s%s\n",(char*)seq->name.s,seq->comment.n?" ":"",seq->comment.n?(char*)seq->comment.s:"");
            print_seq(stdout,s,l,line_len);
            printf("+\n"); print_seq(stdout,q,l,line_len);
        } else if (fake_qual) {
            if(no_comment) printf("@%s\n",(char*)seq->name.s);
            else printf("@%s%s%s\n",(char*)seq->name.s,seq->comment.n?" ":"",seq->comment.n?(char*)seq->comment.s:"");
            print_seq(stdout,s,l,line_len);
            printf("+\n"); for(i=0;i<l;i++) putchar(fake_qual); putchar('\n');
        } else {
            if(no_comment) printf(">%s\n",(char*)seq->name.s);
            else printf(">%s%s%s\n",(char*)seq->name.s,seq->comment.n?" ":"",seq->comment.n?(char*)seq->comment.s:"");
            print_seq(stdout,s,l,line_len);
        }
    }
    kseq_destroy(seq); gzclose(fp);
    if(mask_bed) regdb_destroy(mask_bed);
    return 0;
}

/* ============================================================
 * size command
 * ============================================================ */
static int stk_size(int argc, char *argv[]) {
    int c; gzFile fp; kseq_t *seq;
    long long nseq=0, nbases=0;
    while((c=getopt(argc,argv,""))!=-1){}
    if (argc-optind==0) return 0;
    fp=xzopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_size] failed to open the input file/stream.\n");return 1;}
    seq=kseq_init(fp);
    while(kseq_read(seq)>=0){nseq++;nbases+=seq->seq.n;}
    kseq_destroy(seq); gzclose(fp);
    printf("%lld\t%lld\n",nseq,nbases);
    return 0;
}

/* ============================================================
 * comp command
 * ============================================================ */
static int stk_comp(int argc, char *argv[]) {
    int c; gzFile fp; kseq_t *seq;
    while((c=getopt(argc,argv,""))!=-1){}
    if (argc-optind==0) return 0;
    fp=xzopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_comp] failed to open the input file/stream.\n");return 1;}
    seq=kseq_init(fp);
    while(kseq_read(seq)>=0) {
        long long nA=0,nC=0,nG=0,nT=0,n2ry=0,n2other=0,n3=0,nN=0,ncpg2=0;
        int prev=0; /* 0=none, 1=was C, 2=was G, 3=was S */
        int i;
        for(i=0;i<(int)seq->seq.n;i++){
            int ch=toupper((uint8_t)seq->seq.s[i]);
            switch(ch){
                case 'A': nA++; prev=0; break;
                case 'C': nC++; prev=1; break;
                case 'G': nG++; if(prev==1)ncpg2+=2; prev=2; break;
                case 'T': nT++; prev=0; break;
                case 'N': nN++; prev=0; break;
                case 'R': n2ry++; prev=0; break;
                case 'Y': n2ry++; prev=0; break;
                case 'S':
                    if(prev==1||prev==2) n2other++;
                    else ncpg2++;
                    prev=0; break;
                case 'W': n2other++; prev=0; break;
                case 'M': n2other++; prev=0; break;
                case 'K': n2other++; prev=0; break;
                case 'H': case 'B': case 'V': case 'D': n3++; prev=0; break;
                default: prev=0; break;
            }
        }
        printf("%s\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t0\n",
               (char*)seq->name.s,(long long)seq->seq.n,nA,nC,nG,nT,n2ry+n2other,n3,nN,ncpg2,n2other,n2ry);
    }
    kseq_destroy(seq); gzclose(fp); return 0;
}

/* ============================================================
 * sample command
 * ============================================================ */
static int stk_sample(int argc, char *argv[]) {
    int c, seed=11, two_pass=0;
    while((c=getopt(argc,argv,"s:2"))!=-1){
        switch(c){case 's':seed=atoi(optarg);break;case '2':two_pass=1;break;}
    }
    if(argc-optind<2){
        fprintf(stderr,"\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\n");
        fprintf(stderr,"Options: -s INT       RNG seed [11]\n");
        fprintf(stderr,"         -2           2-pass mode: twice as slow but with much reduced memory\n\n");
        return 1;
    }
    char *end; double frac=strtod(argv[optind+1],&end);
    int is_frac = (*end=='\0' && frac>0.0 && frac<1.0);
    int nreads = is_frac ? 0 : (int)atol(argv[optind+1]);

    /* Reservoir sampling */
    gzFile fp; kseq_t *seq;
    uint32_t rs = seed * 1103515245 + 12345;

    if (is_frac) {
        fp=xzopen(argv[optind],"r");
        if(!fp){fprintf(stderr,"[E::stk_sample] failed to open file.\n");return 1;}
        seq=kseq_init(fp);
        while(kseq_read(seq)>=0){
            rs=rs*1103515245+12345;
            double r=(double)(rs>>1)/(double)0x7fffffff;
            if(r<frac){
                if(seq->qual.n){
                    printf("@%s\n%s\n+\n%s\n",(char*)seq->name.s,(char*)seq->seq.s,(char*)seq->qual.s);
                } else {
                    printf(">%s\n%s\n",(char*)seq->name.s,(char*)seq->seq.s);
                }
            }
        }
        kseq_destroy(seq); gzclose(fp);
    } else {
        /* Reservoir sampling for fixed count */
        /* First pass: count total reads */
        typedef struct { char *name, *seq, *qual; } rec_t;
        rec_t *res = calloc(nreads, sizeof(rec_t));
        long long ntot = 0;

        fp=xzopen(argv[optind],"r");
        if(!fp){fprintf(stderr,"[E::stk_sample] failed to open file.\n");free(res);return 1;}
        seq=kseq_init(fp);
        while(kseq_read(seq)>=0){
            ntot++;
            rs=rs*1103515245+12345;
            if(ntot<=nreads){
                int idx=ntot-1;
                res[idx].name=strdup((char*)seq->name.s);
                res[idx].seq=strdup((char*)seq->seq.s);
                res[idx].qual=seq->qual.n?strdup((char*)seq->qual.s):NULL;
            } else {
                long long j = (long long)(rs>>1) % ntot;
                if(j<nreads){
                    int idx=(int)j;
                    free(res[idx].name); free(res[idx].seq); free(res[idx].qual);
                    res[idx].name=strdup((char*)seq->name.s);
                    res[idx].seq=strdup((char*)seq->seq.s);
                    res[idx].qual=seq->qual.n?strdup((char*)seq->qual.s):NULL;
                }
            }
        }
        kseq_destroy(seq); gzclose(fp);
        int n = ntot < nreads ? (int)ntot : nreads;
        int i;
        for(i=0;i<n;i++){
            if(res[i].qual) printf("@%s\n%s\n+\n%s\n",res[i].name,res[i].seq,res[i].qual);
            else printf(">%s\n%s\n",res[i].name,res[i].seq);
            free(res[i].name); free(res[i].seq); free(res[i].qual);
        }
        free(res);
    }
    return 0;
}

/* ============================================================
 * subseq command
 * ============================================================ */
static int stk_subseq(int argc, char *argv[]) {
    int c, tab=0, strand_aware=0, line_len=0;
    while((c=getopt(argc,argv,"tsl:"))!=-1){
        switch(c){case 't':tab=1;break;case 's':strand_aware=1;break;case 'l':line_len=atoi(optarg);break;}
    }
    if(argc-optind<2){
