                    /* we need a way to match regs to sequences */
                    /* simple approach: since BED is usually sorted, iterate all */
                    /* actually we need to know which reg belongs to which seq */
                    /* Let me use a different approach */
                    (void)r;
                }
                /* Use a proper approach with offsets */
                /* The regdb stores regs in order of insertion */
                /* We need to find regs for this sequence by iterating */
                int base=bed->offs[idx];
                /* We need to know how many regs for this seq */
                /* cnts[] was repurposed during finalize - let's recalculate */
                /* Actually I stored offs but zeroed cnts during finalize */
                /* Let me use a workaround: iterate all regs and check seqname */
                /* This is slow but correct */
