static void kseq_close(kseq_t*ks){if(!ks)return;free(ks->name.s);free(ks->comment.s);free(ks->seq.s);free(ks->qual.s);kstrm_close(ks->f);free(ks);}
static int kseq_read(kseq_t*seq){
    int c; kstrm_t*ks=seq->f;
    if(!seq->last){while((c=kstrm_gc(ks))!=-1&&c!='>'&&c!='@');if(c==-1)return -1;seq->last=c;}
    seq->comment.n=seq->seq.n=seq->qual.n=0;
    if(kstrm_until(ks,0,&seq->name,&c)<0)return -1;
    if(c!='\n')kstrm_until(ks,'\n',&seq->comment,0);
    while((c=kstrm_gc(ks))!=-1&&c!='>'&&c!='+'&&c!='@'){
        if(c=='\n')continue;
        if(seq->seq.n+1>=(int64_t)seq->seq.m){seq->seq.m=seq->seq.m<16?32:seq->seq.m*2;seq->seq.s=realloc(seq->seq.s,seq->seq.m);}
        seq->seq.s[seq->seq.n++]=c;
        kstrm_until(ks,'\n',&seq->seq,0);
    }
    if(seq->seq.n+1>=(int64_t)seq->seq.m){seq->seq.m=seq->seq.n+2;seq->seq.s=realloc(seq->seq.s,seq->seq.m);}
    seq->seq.s[seq->seq.n]=0;
    if(c=='>'||c=='@'){seq->last=c;return seq->seq.n;}
    if(c=='+'){
        seq->last=0;
        if(seq->qual.m<seq->seq.m){seq->qual.m=seq->seq.m;seq->qual.s=realloc(seq->qual.s,seq->qual.m);}
        while((c=kstrm_gc(ks))!=-1&&c!='\n');
        while(seq->qual.n<seq->seq.n&&(c=kstrm_gc(ks))!=-1){
            if(c=='\n')continue;
            seq->qual.s[seq->qual.n++]=c;
            kstrm_until(ks,'\n',&seq->qual,0);
        }
        seq->qual.s[seq->qual.n]=0;
    }else seq->last=c;
    return seq->seq.n;
}

/* =============================== tables =============================== */
static uint8_t comp_tab[256], nt4[256], iupac_ch[16];
static int tabs_init=0;
static void init_tables(void){
    int i; if(tabs_init)return; tabs_init=1;
    for(i=0;i<256;i++)comp_tab[i]=i;
    comp_tab['A']='T';comp_tab['T']='A';comp_tab['C']='G';comp_tab['G']='C';
    comp_tab['a']='t';comp_tab['t']='a';comp_tab['c']='g';comp_tab['g']='c';
    comp_tab['R']='Y';comp_tab['Y']='R';comp_tab['r']='y';comp_tab['y']='r';
    comp_tab['S']='S';comp_tab['s']='s';comp_tab['W']='W';comp_tab['w']='w';
    comp_tab['K']='M';comp_tab['M']='K';comp_tab['k']='m';comp_tab['m']='k';
    comp_tab['H']='D';comp_tab['D']='H';comp_tab['h']='d';comp_tab['d']='h';
    comp_tab['B']='V';comp_tab['V']='B';comp_tab['b']='v';comp_tab['v']='b';
    comp_tab['N']='N';comp_tab['n']='n';
    memset(nt4,15,256);
    nt4['A']=nt4['a']=1;nt4['C']=nt4['c']=2;nt4['G']=nt4['g']=4;nt4['T']=nt4['t']=8;
    nt4['R']=nt4['r']=5;nt4['Y']=nt4['y']=10;nt4['S']=nt4['s']=6;nt4['W']=nt4['w']=9;
    nt4['K']=nt4['k']=12;nt4['M']=nt4['m']=3;nt4['B']=nt4['b']=14;nt4['D']=nt4['d']=13;
    nt4['H']=nt4['h']=11;nt4['V']=nt4['v']=7;nt4['N']=nt4['n']=15;
    iupac_ch[0]='N';iupac_ch[1]='A';iupac_ch[2]='C';iupac_ch[3]='M';
    iupac_ch[4]='G';iupac_ch[5]='R';iupac_ch[6]='S';iupac_ch[7]='V';
    iupac_ch[8]='T';iupac_ch[9]='W';iupac_ch[10]='Y';iupac_ch[11]='H';
    iupac_ch[12]='K';iupac_ch[13]='D';iupac_ch[14]='B';iupac_ch[15]='N';
}
static void revcomp(char*s,int l){
    int i; init_tables();
    for(i=0;i<l/2;i++){char t=comp_tab[(uint8_t)s[i]];s[i]=comp_tab[(uint8_t)s[l-1-i]];s[l-1-i]=t;}
    if(l&1)s[l/2]=comp_tab[(uint8_t)s[l/2]];
}

/* =============================== utils =============================== */
static gzFile xzopen(const char*fn,const char*mode){
    gzFile fp;
    if(!strcmp(fn,"-"))fp=gzdopen(fileno(stdin),mode);
    else fp=gzopen(fn,mode);
    return fp;
}
static void print_seq(FILE*out,const char*s,int l,int ll){
    if(ll<=0||ll>=l){fwrite(s,1,l,out);fputc('\n',out);}
    else{int i;for(i=0;i<l;i+=ll){int n=l-i<ll?l-i:ll;fwrite(s+i,1,n,out);fputc('\n',out);}}
}

/* =============================== name hash =============================== */
#define NHB 65537
typedef struct nhe_s{char*k;int v;struct nhe_s*nx;}nhe_t;
typedef struct{nhe_t*h[NHB];int n;}nhash_t;
static uint32_t nhash_fn(const char*s){uint32_t h=5381;while(*s)h=((h<<5)+h)+(uint8_t)*s++;return h;}
static nhash_t *nhash_new(void){return calloc(1,sizeof(nhash_t));}
static void nhash_free(nhash_t*h){int i;if(!h)return;for(i=0;i<NHB;i++){nhe_t*p=h->h[i];while(p){nhe_t*q=p->nx;free(p->k);free(p);p=q;}}free(h);}
static int nhash_get(nhash_t*h,const char*k){uint32_t b=nhash_fn(k)%NHB;nhe_t*p=h->h[b];while(p){if(!strcmp(p->k,k))return p->v;p=p->nx;}return -1;}
static int nhash_put(nhash_t*h,const char*k){uint32_t b=nhash_fn(k)%NHB;nhe_t*p=h->h[b];while(p){if(!strcmp(p->k,k))return p->v;p=p->nx;}p=calloc(1,sizeof*p);p->k=strdup(k);p->v=h->n++;p->nx=h->h[b];h->h[b]=p;return p->v;}

/* =============================== BED =============================== */
typedef struct{int beg,end,rev,seqidx;}reg_t;
typedef struct{nhash_t*names;int ns,ms,nr,mr;int*cnts,*offs;reg_t*regs;}rdb_t;
static rdb_t *rdb_new(void){rdb_t*r=calloc(1,sizeof*r);r->names=nhash_new();return r;}
static void rdb_free(rdb_t*r){if(!r)return;nhash_free(r->names);free(r->cnts);free(r->offs);free(r->regs);free(r);}
static void rdb_add(rdb_t*db,const char*chr,int b,int e,int rev){
    int idx=nhash_put(db->names,chr);
    while(idx>=db->ms){int o=db->ms;db->ms=db->ms<8?8:db->ms*2;db->cnts=realloc(db->cnts,db->ms*sizeof(int));db->offs=realloc(db->offs,db->ms*sizeof(int));memset(db->cnts+o,0,(db->ms-o)*sizeof(int));memset(db->offs+o,0,(db->ms-o)*sizeof(int));}
    if(idx>=db->ns)db->ns=idx+1;
    db->cnts[idx]++;
    if(db->nr>=db->mr){db->mr=db->mr<8?8:db->mr*2;db->regs=realloc(db->regs,db->mr*sizeof(reg_t));}
    db->regs[db->nr].beg=b;db->regs[db->nr].end=e;db->regs[db->nr].rev=rev;db->regs[db->nr].seqidx=idx;db->nr++;
}
static void rdb_build(rdb_t*db){
    /* Build offset table - store original counts, then zero for re-use */
    int*cnts=malloc(db->ns*sizeof(int));
    memcpy(cnts,db->cnts,db->ns*sizeof(int));
    int i,off=0;for(i=0;i<db->ns;i++){db->offs[i]=off;off+=cnts[i];}
    /* Reorder regs by sequence */
    reg_t*tmp=malloc(db->nr*sizeof(reg_t));
    memset(db->cnts,0,db->ns*sizeof(int));
    for(i=0;i<db->nr;i++){int si=db->regs[i].seqidx;tmp[db->offs[si]+db->cnts[si]++]=db->regs[i];}
    memcpy(db->regs,tmp,db->nr*sizeof(reg_t));
    free(tmp);free(cnts);
}
static rdb_t *read_bed(const char*fn){
    FILE*fp;char buf[65536];rdb_t*db;
    fp=fopen(fn,"r");if(!fp)return NULL;
    db=rdb_new();
    while(fgets(buf,sizeof buf,fp)){
        char*f[8];int nf=0;char*p=buf;
        while(*p&&nf<8){f[nf++]=p;while(*p&&*p!='\t'&&*p!='\n')p++;if(*p)*p++=0;}
        if(nf<3)continue;
        int b=atoi(f[1]),e=atoi(f[2]);
        char strand=nf>=6?f[5][0]:'+';
        rdb_add(db,f[0],b,e,strand=='-'?1:0);
    }
    fclose(fp); rdb_build(db); return db;
}
static nhash_t *read_names(const char*fn){
    FILE*fp;char buf[65536];nhash_t*h;
    fp=fopen(fn,"r");if(!fp)return NULL;
    h=nhash_new();
    while(fgets(buf,sizeof buf,fp)){
        int l=strlen(buf);
        while(l>0&&(buf[l-1]=='\n'||buf[l-1]=='\r'))buf[--l]=0;
        if(l>0)nhash_put(h,buf);
    }
    fclose(fp);return h;
}
static int file_is_bed(const char*fn){
    FILE*fp;char buf[4096];int tabs=0;
    fp=fopen(fn,"r");if(!fp)return 0;
    if(fgets(buf,sizeof buf,fp)){char*p=buf;while(*p&&*p!='\n'){if(*p=='\t')tabs++;p++;}}
    fclose(fp);return tabs>=2;
}

/* =============================== seq =============================== */
static int stk_seq(int argc,char*argv[]){
    int c,ll=0,qt=0,qs=33,mc=0,upper=0,rev=0,tofa=0,nocom=0,dropn=0,minl=0,maxl=0,pm=0,both=0;
    double frac=1.0; int seed=11; char fq=0; char*mfile=NULL; rdb_t*mbed=NULL; int sc=0;
    init_tables();
    while((c=getopt(argc,argv,"aACUl:q:Q:n:f:s:F:rR12NL:X:M:"))!=-1){
        switch(c){
            case 'a':case 'A':tofa=1;break;case 'C':nocom=1;break;case 'U':upper=1;break;
            case 'l':ll=atoi(optarg);break;case 'q':qt=atoi(optarg);break;case 'Q':qs=atoi(optarg);break;
            case 'n':mc=optarg[0];break;case 'f':frac=atof(optarg);break;case 's':seed=atoi(optarg);break;
            case 'F':fq=optarg[0];break;case 'r':rev=1;break;case 'R':both=1;break;
            case '1':pm=1;break;case '2':pm=2;break;case 'N':dropn=1;break;
            case 'L':minl=atoi(optarg);break;case 'X':maxl=atoi(optarg);break;case 'M':mfile=optarg;break;
            default:fprintf(stderr,"seq: invalid option -- '%c'\n",c);break;
        }
    }
    if(argc-optind==0)return 0;
    if(mfile)mbed=read_bed(mfile);
    uint32_t rs=(uint32_t)seed*1103515245+12345;
    gzFile fp=xzopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_seq] failed to open the input file/stream.\n");return 1;}
    kseq_t*seq=kseq_open(fp);
    while(kseq_read(seq)>=0){
        int i,l=(int)seq->seq.n;
        char*s=(char*)seq->seq.s,*q=seq->qual.n?(char*)seq->qual.s:NULL;
        sc++;
        if(pm==1&&(sc%2)==0)continue;
        if(pm==2&&(sc%2)==1)continue;
        if(frac<1.0){rs=rs*1103515245+12345;if((double)(rs>>1)/(double)0x7fffffff>=frac)continue;}
        if(minl>0&&l<minl)continue;
        if(maxl>0&&l>maxl)continue;
        if(dropn){int hn=0;for(i=0;i<l;i++)if(toupper((uint8_t)s[i])=='N'){hn=1;break;}if(hn)continue;}
        if(q&&qt>0)for(i=0;i<l;i++){int qv=(uint8_t)q[i]-qs;if(qv<qt){if(mc)s[i]=mc;else s[i]=tolower((uint8_t)s[i]);}}
        if(upper)for(i=0;i<l;i++)s[i]=toupper((uint8_t)s[i]);
        if(mbed){
            int idx=nhash_get(mbed->names,(char*)seq->name.s);
            if(idx>=0&&idx<mbed->ns){
                int j,base=mbed->offs[idx],cnt=mbed->cnts[idx];
                for(j=base;j<base+cnt;j++){
                    int rb=mbed->regs[j].beg<l?mbed->regs[j].beg:l;
                    int re=mbed->regs[j].end<l?mbed->regs[j].end:l;
                    int k;for(k=rb;k<re;k++)s[k]=tolower((uint8_t)s[k]);
                }
            }
        }
        if(rev){revcomp(s,l);if(q){int h;for(h=0;h<l/2;h++){char t=q[h];q[h]=q[l-1-h];q[l-1-h]=t;}}}
        if(both){
            char*s2=strdup(s); printf(">%s+\n",(char*)seq->name.s); print_seq(stdout,s,l,ll);
            revcomp(s2,l); printf(">%s-\n",(char*)seq->name.s); print_seq(stdout,s2,l,ll); free(s2);
        }else if(q&&!tofa&&!fq){
            if(nocom)printf("@%s\n",(char*)seq->name.s);
            else printf("@%s%s%s\n",(char*)seq->name.s,seq->comment.n?" ":"",seq->comment.n?(char*)seq->comment.s:"");
            print_seq(stdout,s,l,ll); printf("+\n"); print_seq(stdout,q,l,ll);
        }else if(fq){
            if(nocom)printf("@%s\n",(char*)seq->name.s);
            else printf("@%s%s%s\n",(char*)seq->name.s,seq->comment.n?" ":"",seq->comment.n?(char*)seq->comment.s:"");
            print_seq(stdout,s,l,ll); printf("+\n"); for(i=0;i<l;i++)putchar(fq); putchar('\n');
        }else{
            if(nocom)printf(">%s\n",(char*)seq->name.s);
            else printf(">%s%s%s\n",(char*)seq->name.s,seq->comment.n?" ":"",seq->comment.n?(char*)seq->comment.s:"");
            print_seq(stdout,s,l,ll);
        }
    }
    kseq_close(seq);gzclose(fp);if(mbed)rdb_free(mbed);return 0;
}

/* =============================== size =============================== */
static int stk_size(int argc,char*argv[]){
    int c; gzFile fp; kseq_t*seq; long long ns=0,nb=0;
    while((c=getopt(argc,argv,""))!=-1){}
    if(argc-optind==0)return 0;
    fp=xzopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_size] failed to open the input file/stream.\n");return 1;}
    seq=kseq_open(fp);
    while(kseq_read(seq)>=0){ns++;nb+=seq->seq.n;}
    kseq_close(seq);gzclose(fp);
    printf("%lld\t%lld\n",ns,nb); return 0;
}

/* =============================== comp =============================== */
static int stk_comp(int argc,char*argv[]){
    int c; gzFile fp; kseq_t*seq;
    while((c=getopt(argc,argv,""))!=-1){}
    if(argc-optind==0)return 0;
    fp=xzopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_comp] failed to open the input file/stream.\n");return 1;}
    seq=kseq_open(fp);
    while(kseq_read(seq)>=0){
        long long nA=0,nC=0,nG=0,nT=0,n2ry=0,n2o=0,n3=0,nN=0,ncpg=0;
        int prev=0,i;
        for(i=0;i<(int)seq->seq.n;i++){
            int ch=toupper((uint8_t)seq->seq.s[i]);
            switch(ch){
                case 'A':nA++;prev=0;break;
                case 'C':nC++;prev=1;break;
                case 'G':nG++;if(prev==1)ncpg+=2;prev=2;break;
                case 'T':nT++;prev=0;break;
                case 'N':nN++;prev=0;break;
                case 'R':n2ry++;prev=0;break;
                case 'Y':n2ry++;prev=0;break;
                case 'S':if(prev==1||prev==2)n2o++;else ncpg++;prev=0;break;
                case 'W':n2o++;prev=0;break;
                case 'M':n2o++;prev=0;break;
                case 'K':n2o++;prev=0;break;
                case 'H':case 'B':case 'V':case 'D':n3++;prev=0;break;
                default:prev=0;break;
            }
        }
        printf("%s\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t0\n",
               (char*)seq->name.s,(long long)seq->seq.n,nA,nC,nG,nT,n2ry+n2o,n3,nN,ncpg,n2o,n2ry);
    }
    kseq_close(seq);gzclose(fp);return 0;
}

/* =============================== sample =============================== */
static int stk_sample(int argc,char*argv[]){
    int c,seed=11;
    while((c=getopt(argc,argv,"s:2"))!=-1){
        switch(c){case 's':seed=atoi(optarg);break;case '2':break;}
    }
    if(argc-optind<2){
        fprintf(stderr,"\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\n");
        fprintf(stderr,"Options: -s INT       RNG seed [11]\n");
        fprintf(stderr,"         -2           2-pass mode: twice as slow but with much reduced memory\n\n");
        return 1;
    }
    char*end; double frac=strtod(argv[optind+1],&end);
    int is_frac=(*end=='\0'&&frac>0.0&&frac<1.0);
    long long nreads=is_frac?0:atoll(argv[optind+1]);
    gzFile fp; kseq_t*seq;
    uint32_t rs=(uint32_t)seed*1103515245+12345;
    if(is_frac){
        fp=xzopen(argv[optind],"r");
        if(!fp){fprintf(stderr,"[E::stk_sample] failed to open file.\n");return 1;}
        seq=kseq_open(fp);
        while(kseq_read(seq)>=0){
            rs=rs*1103515245+12345;
            if((double)(rs>>1)/(double)0x7fffffff<frac){
                if(seq->qual.n)printf("@%s\n%s\n+\n%s\n",(char*)seq->name.s,(char*)seq->seq.s,(char*)seq->qual.s);
                else printf(">%s\n%s\n",(char*)seq->name.s,(char*)seq->seq.s);
            }
        }
        kseq_close(seq);gzclose(fp);
    }else{
        typedef struct{char*name,*seq,*qual;}rec_t;
        rec_t*res=calloc(nreads,sizeof(rec_t));
        long long ntot=0;
        fp=xzopen(argv[optind],"r");
        if(!fp){fprintf(stderr,"[E::stk_sample] failed to open file.\n");free(res);return 1;}
        seq=kseq_open(fp);
        while(kseq_read(seq)>=0){
            ntot++;
            rs=rs*1103515245+12345;
            if(ntot<=nreads){
                int idx=ntot-1;
                res[idx].name=strdup((char*)seq->name.s);
                res[idx].seq=strdup((char*)seq->seq.s);
                res[idx].qual=seq->qual.n?strdup((char*)seq->qual.s):NULL;
            }else{
                long long j=(long long)(rs>>1)%ntot;
                if(j<nreads){
                    int idx=(int)j;
                    free(res[idx].name);free(res[idx].seq);free(res[idx].qual);
                    res[idx].name=strdup((char*)seq->name.s);
                    res[idx].seq=strdup((char*)seq->seq.s);
                    res[idx].qual=seq->qual.n?strdup((char*)seq->qual.s):NULL;
                }
            }
        }
        kseq_close(seq);gzclose(fp);
        long long n=ntot<nreads?ntot:nreads; int i;
        for(i=0;i<n;i++){
            if(res[i].qual)printf("@%s\n%s\n+\n%s\n",res[i].name,res[i].seq,res[i].qual);
            else printf(">%s\n%s\n",res[i].name,res[i].seq);
            free(res[i].name);free(res[i].seq);free(res[i].qual);
        }
        free(res);
    }
    return 0;
}

/* =============================== subseq =============================== */
static int stk_subseq(int argc,char*argv[]){
    int c,tab=0,strand=0,ll=0;
    while((c=getopt(argc,argv,"tsl:"))!=-1){switch(c){case 't':tab=1;break;case 's':strand=1;break;case 'l':ll=atoi(optarg);break;}}
    if(argc-optind<2){
        fprintf(stderr,"Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\n");
        fprintf(stderr,"Options:\n  -t       TAB delimited output\n  -s       strand aware\n  -l INT   sequence line length [0]\n");
        fprintf(stderr,"Note: Use 'samtools faidx' if only a few regions are intended.\n");
        return 0;
    }
    int use_bed=file_is_bed(argv[optind+1]);
    rdb_t*bed=NULL; nhash_t*names=NULL;
    if(use_bed)bed=read_bed(argv[optind+1]);
    else names=read_names(argv[optind+1]);
    gzFile fp=xzopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_subseq] failed to open file.\n");return 1;}
    kseq_t*seq=kseq_open(fp); init_tables();
    while(kseq_read(seq)>=0){
        char*nm=(char*)seq->name.s,*s=(char*)seq->seq.s; int l=(int)seq->seq.n;
        if(use_bed){
            int idx=nhash_get(bed->names,nm);
            if(idx>=0&&idx<bed->ns){
                int j,base=bed->offs[idx],cnt=bed->cnts[idx];
                for(j=base;j<base+cnt;j++){
                    int b=bed->regs[j].beg,e=bed->regs[j].end;
                    if(b>l)b=l; if(e>l)e=l;
                    int sl=e-b; if(sl<=0)continue;
                    char*sub=strndup(s+b,sl);
                    if(strand&&bed->regs[j].rev)revcomp(sub,sl);
                    if(tab)printf("%s\t%d\t%s\n",nm,b+1,sub);
                    else{printf(">%s:%d-%d\n",nm,b+1,e);print_seq(stdout,sub,sl,ll);}
                    free(sub);
                }
            }
        }else{
            if(nhash_get(names,nm)>=0){
                if(tab)printf("%s\t0\t%s\n",nm,s);
                else{printf(">%s\n",nm);print_seq(stdout,s,l,ll);}
            }
        }
    }
    kseq_close(seq);gzclose(fp);if(bed)rdb_free(bed);if(names)nhash_free(names);return 0;
}

/* =============================== fqchk =============================== */
#define FQCHK_MAX_LEN 100000
static int stk_fqchk(int argc,char*argv[]){
