    long long *pn=calloc(FQCHK_MAX_LEN+1,sizeof(long long));
    double *pq=calloc(FQCHK_MAX_LEN+1,sizeof(double)); /* sum of error probs */
    long long *plow=calloc(FQCHK_MAX_LEN+1,sizeof(long long));
