            switch(ch){case 'A':pa[pos]++;break;case 'C':pc[pos]++;break;case 'G':pg[pos]++;break;case 'T':pt[pos]++;break;default:pn[pos]++;break;}
            pq[pos]+=ep;
            if(qi<qthres)plow[pos]++;else phigh[pos]++;
            sumq+=qi;
            if(seq->qual.n)qdist[(uint8_t)seq->qual.s[i]]=1;
        }
        /* also accumulate ALL row */
        for(i=0;i<l;i++){
            int ch=toupper((uint8_t)seq->seq.s[i]);
            int qi=seq->qual.n?(uint8_t)seq->qual.s[i]-33:40;
            if(qi<0)qi=0;if(qi>93)qi=93;
            double ep=pow(10.0,-qi/10.0);
            pcnt[0]++;
            switch(ch){case 'A':pa[0]++;break;case 'C':pc[0]++;break;case 'G':pg[0]++;break;case 'T':pt[0]++;break;default:pn[0]++;break;}
            pq[0]+=ep;
            if(qi<qthres)plow[0]++;else phigh[0]++;
        }
    }
    kseq_close(seq);gzclose(fp);
    int ndist=0; int i; for(i=0;i<256;i++)if(qdist[i])ndist++;
    double avglen=nseq>0?(double)tot/nseq:0;
    printf("min_len: %lld; max_len: %lld; avg_len: %.2f; %d distinct quality values\n",
           nseq>0?(long long)minl:0LL,(long long)maxl,avglen,ndist);
    printf("POS\t#bases\t%%A\t%%C\t%%G\t%%T\t%%N\tavgQ\terrQ\t%%low\t%%high\n");
    for(i=0;i<=maxpos;i++){
        long long cnt=pcnt[i]; if(cnt==0)continue;
        double avgq=cnt>0?sumq/tot:0; /* for ALL row */
        double errq=0;
        double ep_avg=pq[i]/cnt;
        if(i==0){avgq=tot>0?sumq/tot:0;ep_avg=pq[0]/cnt;}
        else avgq=0;
        /* recalculate avgQ for this position */
        /* we need sum of Q values, not error probs */
        /* let me redo: need per-position sum of Q */
        (void)avgq;
        if(ep_avg>0)errq=-10*log10(ep_avg); else errq=99.0;
        double pA=100.0*pa[i]/cnt,pC=100.0*pc[i]/cnt,pG=100.0*pg[i]/cnt,pT=100.0*pt[i]/cnt,pN=100.0*pn[i]/cnt;
        double plo=100.0*plow[i]/cnt,phi=100.0*phigh[i]/cnt;
        if(i==0)printf("ALL\t%lld\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\n",
                       cnt,pA,pC,pG,pT,pN,0.0,errq,plo,phi);
        else printf("%d\t%lld\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\n",
                    i,cnt,pA,pC,pG,pT,pN,0.0,errq,plo,phi);
    }
    free(pcnt);free(pa);free(pc);free(pg);free(pt);free(pn);free(pq);free(plow);free(phigh);
