/* Test: fix kseq - the kstrm_until should not reset n, callers should do it */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
#include <stdint.h>
#include <ctype.h>

#define KBUFSZ 16384
typedef struct { uint8_t *buf; int beg,end,eof; gzFile f; } kstrm_t;
typedef struct { int64_t n,m; uint8_t *s; } kstr_t;
typedef struct { kstr_t name,comment,seq,qual; int last; kstrm_t *f; } kseq_t;

static kstrm_t *kstrm_open(gzFile f){kstrm_t*ks=calloc(1,sizeof*ks);ks->f=f;ks->buf=malloc(KBUFSZ);return ks;}
static int kstrm_gc(kstrm_t*ks){
    if(ks->eof&&ks->beg>=ks->end)return -1;
    if(ks->beg>=ks->end){ks->beg=0;ks->end=gzread(ks->f,ks->buf,KBUFSZ);if(!ks->end){ks->eof=1;return -1;}}
    return ks->buf[ks->beg++];
}

/* append-mode: does NOT reset s->n; caller must reset */
static int kstrm_getuntil(kstrm_t*ks,int delim,kstr_t*s,int*dr){
    int any=0; if(dr)*dr=0;
    for(;;){
        int i;
        if(ks->beg>=ks->end){if(!ks->eof){ks->beg=0;ks->end=gzread(ks->f,ks->buf,KBUFSZ);if(!ks->end){ks->eof=1;break;}}else break;}
        if(delim=='\n'){for(i=ks->beg;i<ks->end;i++)if(ks->buf[i]=='\n')break;}
        else{for(i=ks->beg;i<ks->end;i++)if(isspace(ks->buf[i]))break;}
        int need=s->n+(i-ks->beg)+2;
        if(need>s->m){s->m=need<8?8:need;s->m=s->m*3/2;s->s=realloc(s->s,s->m);}
        any=1; memcpy(s->s+s->n,ks->buf+ks->beg,i-ks->beg); s->n+=i-ks->beg; ks->beg=i+1;
        if(i<ks->end){if(dr)*dr=ks->buf[i];break;}
    }
    if(!s->s){s->m=1;s->s=calloc(1,1);}else if(!any)return -1;
    s->s[s->n]=0; return s->n;
}
static kseq_t *kseq_open(gzFile fd){kseq_t*s=calloc(1,sizeof*s);s->f=kstrm_open(fd);return s;}
static int kseq_read(kseq_t*seq){
    int c; kstrm_t*ks=seq->f;
    if(!seq->last){while((c=kstrm_gc(ks))!=-1&&c!='>'&&c!='@');if(c==-1)return -1;seq->last=c;}
    seq->comment.n=seq->seq.n=seq->qual.n=0;  /* reset here */
    if(kstrm_getuntil(ks,0,&seq->name,&c)<0)return -1;
    if(c!='\n'){seq->comment.n=0;kstrm_getuntil(ks,'\n',&seq->comment,0);}
    while((c=kstrm_gc(ks))!=-1&&c!='>'&&c!='+'&&c!='@'){
        if(c=='\n')continue;
        /* append c then rest of line */
        if(seq->seq.n+1>=(int64_t)seq->seq.m){seq->seq.m=seq->seq.m<16?32:seq->seq.m*2;seq->seq.s=realloc(seq->seq.s,seq->seq.m);}
        seq->seq.s[seq->seq.n++]=c;
        /* now append rest of line WITHOUT resetting n */
        kstrm_getuntil(ks,'\n',&seq->seq,0);
    }
    if(seq->seq.n+1>=(int64_t)seq->seq.m){seq->seq.m=seq->seq.n+2;seq->seq.s=realloc(seq->seq.s,seq->seq.m);}
    seq->seq.s[seq->seq.n]=0;
    if(c=='>'||c=='@'){seq->last=c;return seq->seq.n;}
    if(c=='+'){
        seq->last=0;
        if(seq->qual.m<seq->seq.m){seq->qual.m=seq->seq.m;seq->qual.s=realloc(seq->qual.s,seq->qual.m);}
        while((c=kstrm_gc(ks))!=-1&&c!='\n');
        while(seq->qual.n<seq->seq.n&&(c=kstrm_gc(ks))!=-1){
            if(c=='\n')continue;
            seq->qual.s[seq->qual.n++]=c;
            kstrm_getuntil(ks,'\n',&seq->qual,0);
        }
        seq->qual.s[seq->qual.n]=0;
    }else seq->last=c;
    return seq->seq.n;
}
int main(){
    gzFile fp=gzdopen(fileno(stdin),"r");
    kseq_t*seq=kseq_open(fp);
    while(kseq_read(seq)>=0)
        printf(">%s\n%s\n",(char*)seq->name.s,(char*)seq->seq.s);
    return 0;
}
