    if(idx>=db->ns)db->ns=idx+1;
    db->cnts[idx]++;
    if(db->nr>=db->mr){db->mr=db->mr<8?8:db->mr*2;db->regs=realloc(db->regs,db->mr*sizeof(Reg));}
