    if(argc-optind<2){
        fprintf(stderr,"\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\n");
        fprintf(stderr,"Options: -s INT       RNG seed [11]\n");
        fprintf(stderr,"         -2           2-pass mode: twice as slow but with much reduced memory\n\n");
        return 1;
    }
    char*end; double frac=strtod(argv[optind+1],&end);
    int is_frac=(*end=='\0'&&frac>0.0&&frac<1.0);
    long long nreads=is_frac?0:atoll(argv[optind+1]);
    uint32_t rs=(uint32_t)seed*1103515245+12345;
    gzFile fp=xopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_sample] failed to open file.\n");return 1;}
    Kseq*seq=kseq_open(fp);
    if(is_frac){
        while(kseq_read(seq)>=0){
            rs=rs*1103515245+12345;
            if((double)(rs>>1)/(double)0x7fffffff<frac){
                if(seq->qual.n)printf("@%s\n%s\n+\n%s\n",(char*)seq->name.s,(char*)seq->seq.s,(char*)seq->qual.s);
                else printf(">%s\n%s\n",(char*)seq->name.s,(char*)seq->seq.s);
            }
        }
        kseq_close(seq);gzclose(fp);
    }else{
        typedef struct{char*name,*seq,*qual;}Rec;
        Rec*res=calloc(nreads,sizeof(Rec));
        long long ntot=0;
        while(kseq_read(seq)>=0){
            ntot++;rs=rs*1103515245+12345;
            if(ntot<=nreads){
                int idx=ntot-1;
                res[idx].name=strdup((char*)seq->name.s);
                res[idx].seq=strdup((char*)seq->seq.s);
                res[idx].qual=seq->qual.n?strdup((char*)seq->qual.s):NULL;
            }else{
                long long j=(long long)(rs>>1)%ntot;
                if(j<nreads){
                    free(res[j].name);free(res[j].seq);free(res[j].qual);
                    res[j].name=strdup((char*)seq->name.s);
                    res[j].seq=strdup((char*)seq->seq.s);
                    res[j].qual=seq->qual.n?strdup((char*)seq->qual.s):NULL;
                }
            }
        }
        kseq_close(seq);gzclose(fp);
        long long n=ntot<nreads?ntot:nreads; int i;
        for(i=0;i<n;i++){
            if(res[i].qual)printf("@%s\n%s\n+\n%s\n",res[i].name,res[i].seq,res[i].qual);
            else printf(">%s\n%s\n",res[i].name,res[i].seq);
            free(res[i].name);free(res[i].seq);free(res[i].qual);
        }
        free(res);
