static int stk_fqchk(int argc,char*argv[]){
    int c,qthres=0;
    while((c=getopt(argc,argv,"q:"))!=-1){switch(c){case 'q':qthres=atoi(optarg);break;default:fprintf(stderr,"fqchk: invalid option -- '%c'\n",c);break;}}
    if(argc-optind==0){fprintf(stderr,"Usage: seqtk fqchk [-q 0] <in.fq>\n");return 1;}
    gzFile fp=xopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_fqchk] failed to open the input file/stream.\n");return 1;}
    Kseq*seq=kseq_open(fp);
    long long tot=0,nseq=0;int minl=INT32_MAX,maxl=0,maxpos=0;
    double sumq=0;
    int MPOS=100001;
    long long *pcnt=calloc(MPOS,8),*pa=calloc(MPOS,8),*pc=calloc(MPOS,8),*pg=calloc(MPOS,8);
    long long *pt=calloc(MPOS,8),*pn=calloc(MPOS,8),*plow=calloc(MPOS,8),*phigh=calloc(MPOS,8);
    double *pq=calloc(MPOS,8),*pqsum=calloc(MPOS,8);
    int qdist[256]={0};
    while(kseq_read(seq)>=0){
        int l=(int)seq->seq.n;nseq++;
        if(l<minl)minl=l;if(l>maxl)maxl=l;
        tot+=l;if(l>maxpos&&l<MPOS)maxpos=l;
        int i;
        for(i=0;i<l;i++){
            int ch=toupper((uint8_t)seq->seq.s[i]);
            int qi=seq->qual.n?(uint8_t)seq->qual.s[i]-33:40;
            if(qi<0)qi=0;if(qi>93)qi=93;
            double ep=pow(10.0,-(double)qi/10.0);
            int pos=i+1<MPOS?i+1:MPOS-1;
            pcnt[pos]++;pcnt[0]++;
            switch(ch){case 'A':pa[pos]++;pa[0]++;break;case 'C':pc[pos]++;pc[0]++;break;
                        case 'G':pg[pos]++;pg[0]++;break;case 'T':pt[pos]++;pt[0]++;break;
                        default:pn[pos]++;pn[0]++;break;}
            pq[pos]+=ep;pq[0]+=ep;
            pqsum[pos]+=qi;pqsum[0]+=qi;
            if(qi<qthres){plow[pos]++;plow[0]++;}else{phigh[pos]++;phigh[0]++;}
            sumq+=qi;
            if(seq->qual.n)qdist[(uint8_t)seq->qual.s[i]]=1;
        }
    }
    kseq_close(seq);gzclose(fp);
    int ndist=0;int i;for(i=0;i<256;i++)if(qdist[i])ndist++;
    double avglen=nseq>0?(double)tot/nseq:0;
    printf("min_len: %lld; max_len: %lld; avg_len: %.2f; %d distinct quality values\n",
           nseq>0?(long long)minl:0LL,(long long)maxl,avglen,ndist);
    printf("POS\t#bases\t%%A\t%%C\t%%G\t%%T\t%%N\tavgQ\terrQ\t%%low\t%%high\n");
    for(i=0;i<=maxpos;i++){
        long long cnt=pcnt[i];if(cnt==0)continue;
        double ep_avg=pq[i]/cnt;
        double errq=ep_avg>0?-10.0*log10(ep_avg):99.0;
        double avgq=pqsum[i]/cnt;
        double pA=100.0*pa[i]/cnt,pC=100.0*pc[i]/cnt,pG=100.0*pg[i]/cnt;
        double pT=100.0*pt[i]/cnt,pN=100.0*pn[i]/cnt;
        double plo=100.0*plow[i]/cnt,phi2=100.0*phigh[i]/cnt;
        if(i==0)printf("ALL\t%lld\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\n",
                       cnt,pA,pC,pG,pT,pN,avgq,errq,plo,phi2);
        else printf("%d\t%lld\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\n",
                    i,cnt,pA,pC,pG,pT,pN,avgq,errq,plo,phi2);
    }
    free(pcnt);free(pa);free(pc);free(pg);free(pt);free(pn);free(pq);free(pqsum);free(plow);free(phigh);
    return 0;
}

