/* dropse command */
static int stk_dropse(int argc,char*argv[]){
    int c;while((c=getopt(argc,argv,""))!=-1){}
    if(argc-optind==0)return 0;
    gzFile fp=xopen(argv[optind],"r");
    if(!fp)return 1;
    Kseq*seq=kseq_open(fp);
    /* Buffer reads pairwise */
    char *n1=NULL,*s1=NULL,*q1=NULL;
    int has_r1=0;
    while(kseq_read(seq)>=0){
        if(!has_r1){
            n1=strdup((char*)seq->name.s);s1=strdup((char*)seq->seq.s);
            q1=seq->qual.n?strdup((char*)seq->qual.s):NULL;has_r1=1;
        }else{
            /* check if they're a pair */
            char*nm=(char*)seq->name.s;
            int paired=1;
            /* compare base names */
            int l1=strlen(n1),l2=strlen(nm);
            if(l1>2&&(n1[l1-2]=='/'&&(n1[l1-1]=='1'||n1[l1-1]=='2'))){
                char tmp1[4096],tmp2[4096];
                strncpy(tmp1,n1,l1-2);tmp1[l1-2]=0;
                if(l2>2&&nm[l2-2]=='/'){strncpy(tmp2,nm,l2-2);tmp2[l2-2]=0;}
                else{strncpy(tmp2,nm,l2);tmp2[l2]=0;}
                if(strcmp(tmp1,tmp2)!=0)paired=0;
            }else if(strcmp(n1,nm)!=0)paired=0;
            if(paired){
                if(q1)printf("@%s\n%s\n+\n%s\n",n1,s1,q1);else printf(">%s\n%s\n",n1,s1);
                if(seq->qual.n)printf("@%s\n%s\n+\n%s\n",nm,(char*)seq->seq.s,(char*)seq->qual.s);
                else printf(">%s\n%s\n",nm,(char*)seq->seq.s);
                free(n1);free(s1);free(q1);n1=NULL;s1=NULL;q1=NULL;has_r1=0;
            }else{
                /* discard n1 and try again with current as new r1 */
                free(n1);free(s1);free(q1);
                n1=strdup(nm);s1=strdup((char*)seq->seq.s);
                q1=seq->qual.n?strdup((char*)seq->qual.s):NULL;
            }
        }
    }
    if(n1){free(n1);free(s1);free(q1);}
    kseq_close(seq);gzclose(fp);return 0;
}

/* rename command */
static int stk_rename(int argc,char*argv[]){
    int c;while((c=getopt(argc,argv,""))!=-1){}
    if(argc-optind<2){fprintf(stderr,"Usage: seqtk rename <in.fa> [prefix]\n");return 1;}
    gzFile fp=xopen(argv[optind],"r");
    if(!fp)return 1;
    char*prefix=argv[optind+1];
    Kseq*seq=kseq_open(fp);int idx=0;
    while(kseq_read(seq)>=0){
        idx++;
        if(seq->qual.n)printf("@%s%d\n%s\n+\n%s\n",prefix,idx,(char*)seq->seq.s,(char*)seq->qual.s);
        else printf(">%s%d\n%s\n",prefix,idx,(char*)seq->seq.s);
    }
    kseq_close(seq);gzclose(fp);return 0;
}

/* randbase command */
static int stk_randbase(int argc,char*argv[]){
    int c;while((c=getopt(argc,argv,""))!=-1){}
    if(argc-optind==0){fprintf(stderr,"Usage: seqtk randbase <in.fa>\n");return 1;}
    gzFile fp=xopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_randbase] failed to open the input file/stream.\n");return 1;}
    Kseq*seq=kseq_open(fp);init_tables();
    uint32_t rs=11*1103515245+12345;
    while(kseq_read(seq)>=0){
        int i,l=(int)seq->seq.n;char*s=(char*)seq->seq.s;
        for(i=0;i<l;i++){
            int b=toupper((uint8_t)s[i]);
            int m=nt4[b];
            if(__builtin_popcount(m)>1){
                /* pick a random base */
                rs=rs*1103515245+12345;
                int bits[4];int nb=0;int j;
                for(j=0;j<4;j++)if(m&(1<<j))bits[nb++]=1<<j;
                int pick=bits[(rs>>1)%nb];
                char nc=iupac[pick];
                s[i]=islower((uint8_t)s[i])?tolower(nc):nc;
            }
        }
        printf(">%s\n%s\n",(char*)seq->name.s,s);
    }
    kseq_close(seq);gzclose(fp);return 0;
}
