/* cutN command */
static int stk_cutN(int argc,char*argv[]){
    int c,n_size=1000,penalty=10,gaps_only=0;
    while((c=getopt(argc,argv,"n:p:g"))!=-1){
        switch(c){case 'n':n_size=atoi(optarg);break;case 'p':penalty=atoi(optarg);break;case 'g':gaps_only=1;break;default:break;}
    }
    if(argc-optind==0){
        fprintf(stderr,"\nUsage:   seqtk cutN [options] <in.fa>\n\n");
        fprintf(stderr,"Options: -n INT    min size of N tract [1000]\n");
        fprintf(stderr,"         -p INT    penalty for a non-N [10]\n");
        fprintf(stderr,"         -g        print gaps only, no sequence\n\n");
        return 1;
    }
    gzFile fp=xopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_cutN] failed to open the input file/stream.\n");return 1;}
    Kseq*seq=kseq_open(fp);
    while(kseq_read(seq)>=0){
        int l=(int)seq->seq.n;char*s=(char*)seq->seq.s;
        /* Find N tracts using score-based approach */
        int*score=calloc(l+1,sizeof(int));
        int i;
        /* score[i] = max N-tract score ending at position i */
        for(i=0;i<l;i++){
            int ch=toupper((uint8_t)s[i]);
            int v=ch=='N'?1:-penalty;
            score[i+1]=score[i]+v;
            if(score[i+1]<0)score[i+1]=0;
        }
        /* Find segments between N tracts */
        /* A cut happens when the N-tract score >= n_size */
        /* Find cut points: where score[i] reaches n_size */
        int prev_end=0;
        i=0;
        while(i<=l){
            /* Find start of N tract */
            int ntstart=-1,ntend=-1;
            int j=i;
            /* scan for N tract */
            int nscore=0;
            int tract_start=-1;
            while(j<l){
                int ch=toupper((uint8_t)s[j]);
                if(ch=='N'){
                    if(tract_start<0)tract_start=j;
                    nscore++;
                }else{
                    nscore-=penalty;
                    if(nscore<=0){
                        if(tract_start>=0&&nscore+penalty>=n_size){
                            /* found a valid N tract */
                            ntstart=tract_start;
                            ntend=j;/* end is after the N region, at the non-N that caused score to drop */
                            /* backtrack to find actual end of N region */
                            while(ntend>ntstart&&toupper((uint8_t)s[ntend-1])!='N')ntend--;
                            break;
                        }
                        tract_start=-1;nscore=0;
                    }
                }
                j++;
            }
            if(tract_start>=0&&ntstart<0){
                /* reached end of sequence with an active N tract */
                if(nscore>=n_size){
                    ntstart=tract_start;ntend=l;
                    while(ntend>ntstart&&toupper((uint8_t)s[ntend-1])!='N')ntend--;
                }
            }
            if(ntstart>=0){
                /* output segment before N tract */
                if(gaps_only){
                    printf("%s\t%d\t%d\n",(char*)seq->name.s,ntstart,ntend);
                }else{
                    int seg_l=ntstart-prev_end;
                    if(seg_l>0){
                        printf(">%s:%d-%d\n",(char*)seq->name.s,prev_end+1,ntstart);
                        prnseq(stdout,s+prev_end,seg_l,60);
                    }
                }
                prev_end=ntend;
                i=ntend;
            }else break;
        }
        /* output remaining */
        if(!gaps_only){
            int seg_l=l-prev_end;
            if(seg_l>0){
                printf(">%s:%d-%d\n",(char*)seq->name.s,prev_end+1,l);
                prnseq(stdout,s+prev_end,seg_l,60);
            }
        }
        free(score);
    }
    kseq_close(seq);gzclose(fp);return 0;
}

