static int stk_gap(int argc,char*argv[]){
    int c,min_l=50;
    while((c=getopt(argc,argv,"l:"))!=-1){switch(c){case 'l':min_l=atoi(optarg);break;default:fprintf(stderr,"gap: invalid option -- '%c'\n",c);break;}}
    if(argc-optind==0)return 0;
    gzFile fp=xopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_gap] failed to open the input file/stream.\n");return 1;}
    Kseq*seq=kseq_open(fp);
    while(kseq_read(seq)>=0){
        int l=(int)seq->seq.n,i,beg=-1;char*s=(char*)seq->seq.s;
        for(i=0;i<=l;i++){
            if(i<l&&toupper((uint8_t)s[i])=='N'){if(beg<0)beg=i;}
            else{if(beg>=0&&i-beg>=min_l)printf("%s\t%d\t%d\n",(char*)seq->name.s,beg,i);beg=-1;}
        }
    }
    kseq_close(seq);gzclose(fp);return 0;
}

