#include <stdlib.h>
int main() {
    int reads = 5, nreads = 3;
    int res[3];

    // Test with srand48 and lrand48 for ALL reads
    for (int seed = 42; seed <= 42; seed++) {
        srand48(seed);
        for (int i=0;i<3;i++) res[i]=i;
        for (int i = 0; i < reads; i++) {
            long j = lrand48() % (i+1);
            if (i < nreads) {
                res[i] = i;
                // Optionally swap
                if (j < i) { int t=res[j]; res[j]=res[i]; res[i]=t; }
            } else {
                if (j < nreads) res[j] = i;
            }
        }
        printf("seed=%d result: read%d read%d read%d\n", seed, res[0]+1, res[1]+1, res[2]+1);
    }

    // Try srand48 with calls for ALL reads (no shuffle fill)
    srand48(11);
    for (int i=0;i<3;i++) res[i]=i;
    for (int i = 0; i < reads; i++) {
        long j = lrand48() % (i+1);
        printf("i=%d j=%ld\n", i, j);
        if (i >= nreads && j < nreads) res[j] = i;
    }
    printf("seed=11 no-swap: read%d read%d read%d\n", res[0]+1, res[1]+1, res[2]+1);

    // Try jrand48 seeding via explicit state
    unsigned short xi[3] = {0x330e, (11 >> 0) & 0xffff, (11 >> 16) & 0xffff};
    printf("\nnrand48 values:");
    for (int i=0;i<6;i++) printf(" %ld", nrand48(xi));
    return 0;
}
