#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define N 20
#define K 5

/* kr_rand from seqtk */
static uint32_t kr_state;
#define kr_srand(s) (kr_state = (s))
static inline uint32_t kr_rand(void) {
    kr_state = kr_state * 1664525L + 1013904223L;
    return kr_state >> 1;
}

int main() {
    int targets_11[K] = {17, 11, 10, 14, 8};
    int targets_42[K] = {18, 19, 8, 9, 6};

    /* Test multiple variants */
    const char *names[] = {"no-rng-first", "all-rng", "all-rng-swap", "all-rng-ntot"};

    for (int seed = 11; seed <= 42; seed += 31) {
        int *target = (seed == 11) ? targets_11 : targets_42;

        /* Variant 1: no RNG for first K */
        kr_srand(seed);
        int res[K]; for(int i=0;i<K;i++) res[i]=i;
        for (int i = K; i < N; i++) {
            uint32_t j = kr_rand() % (i+1);
            if ((int)j < K) res[j] = i;
        }
        printf("seed=%d v1: ", seed);
        int match=1; for(int i=0;i<K;i++){printf("r%d ",res[i]+1);if(res[i]!=target[i])match=0;}
        printf("%s\n", match?"MATCH":"");

        /* Variant 2: RNG for ALL reads, no swap */
        kr_srand(seed);
        for(int i=0;i<K;i++) res[i]=i;
        for (int i = 0; i < N; i++) {
            uint32_t j = kr_rand() % (i+1);
            if (i >= K && (int)j < K) res[j] = i;
        }
        printf("seed=%d v2: ", seed);
        match=1; for(int i=0;i<K;i++){printf("r%d ",res[i]+1);if(res[i]!=target[i])match=0;}
        printf("%s\n", match?"MATCH":"");

        /* Variant 3: RNG for ALL reads, with swap during fill */
        kr_srand(seed);
        for(int i=0;i<K;i++) res[i]=i;
        for (int i = 0; i < N; i++) {
            uint32_t j = kr_rand() % (i+1);
            if (i < K) {
                res[i] = i;
                if ((int)j < i) { int t=res[i]; res[i]=res[j]; res[j]=t; }
            } else if ((int)j < K) res[j] = i;
        }
        printf("seed=%d v3: ", seed);
        match=1; for(int i=0;i<K;i++){printf("r%d ",res[i]+1);if(res[i]!=target[i])match=0;}
        printf("%s\n", match?"MATCH":"");

        /* Variant 4: no RNG first, but ntot starts at 1 not K+1 */
        kr_srand(seed);
        for(int i=0;i<K;i++) res[i]=i;
        for (int i = K; i < N; i++) {
            uint32_t j = kr_rand() % (i);  /* use i not i+1 */
            if ((int)j < K) res[j] = i;
        }
        printf("seed=%d v4: ", seed);
        match=1; for(int i=0;i<K;i++){printf("r%d ",res[i]+1);if(res[i]!=target[i])match=0;}
        printf("%s\n", match?"MATCH":"");

