#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define N 20
#define K 5

int check(int res[], int target[]) {
    for(int i=0;i<K;i++) if(res[i]!=target[i]) return 0;
    return 1;
}

int main() {
    int t11[K] = {17,11,10,14,8};
    int t42[K] = {18,19,8,9,6};

    printf("Testing lrand48 variants...\n");

    for (int variant = 0; variant < 16; variant++) {
        for (int seed = 11; seed <= 42; seed += 31) {
            int *target = (seed==11)?t11:t42;
            int res[K]; for(int i=0;i<K;i++) res[i]=i;

            srand48(seed);

            // variant bits: [0]=call_for_first_k, [1]=use_modulo_i_not_i1, [2]=swap_fill, [3]=skip_one
            int call_first = variant & 1;
            int mod_i = (variant>>1) & 1;
            int swap_fill = (variant>>2) & 1;

            if (variant>>3) {
                lrand48(); // extra call before start
            }

            for (int i = 0; i < N; i++) {
                long rval;
                if (i < K && !call_first) {
                    if (swap_fill && i > 0) {
                        rval = lrand48();
                        long j = rval % i;
                        if (j < K && j < i) { int t=res[i]; res[i]=res[j]; res[j]=t; }
                    }
                    continue;
                }
                rval = lrand48();
                long denom = mod_i ? i : (i+1);
                if (denom < 1) denom = 1;
                long j = rval % denom;
                if (i < K) {
                    res[i] = i;
                    if (swap_fill && j < i) { int t=res[i]; res[i]=res[j]; res[j]=t; }
                } else if (j < K) res[j] = i;
            }

            if (check(res, target)) {
                printf("MATCH variant=%d seed=%d: ", variant, seed);
                for(int i=0;i<K;i++) printf("r%d ",res[i]+1);
                printf("\n");
            }
        }
    }
    return 0;
}
