int test_2p(uint32_t a, uint32_t c, int n, int k, int ns) {
    int tot = 0;
    for (int seed = 1; seed <= ns; seed++) {
        uint32_t state = seed;
        int acc = 0, res[5], ri = 0;
        for (int i = 0; i < n && acc < k; i++) {
            state = state * a + c;
            uint32_t rv = state >> 1;
            int nr = n-i, kr = k-acc;
            if ((uint64_t)rv * nr < (uint64_t)kr * (1u<<31)) {
                if (ri < k) res[ri++] = i; acc++;
            }
        }
        /* fill remaining slots if needed */
        while (ri < k && ri < 3) { res[ri] = -1; ri++; }
        int ok = 1;
        for (int i=0; i<k; i++) if (res[i] != expected_2p[seed-1][i]) { ok=0; break; }
        tot += ok;
    }
    return tot;
}

