#define KBSZ 16384
typedef struct { uint8_t *buf; int beg,end,eof; gzFile f; } KS;
typedef struct { int64_t n,m; uint8_t *s; } KStr;
typedef struct { KStr name,comment,seq,qual; int last; KS *f; } Kseq;

static KS *ks_open(gzFile f){KS*k=calloc(1,sizeof*k);k->f=f;k->buf=malloc(KBSZ);return k;}
static void ks_close(KS*k){if(k){free(k->buf);free(k);}}
static int ks_gc(KS*k){
    if(k->eof&&k->beg>=k->end)return -1;
    if(k->beg>=k->end){k->beg=0;k->end=gzread(k->f,k->buf,KBSZ);if(!k->end){k->eof=1;return -1;}}
    return k->buf[k->beg++];
}
static int ks_getuntil(KS*k,int delim,KStr*s,int*dr){
    int any=0; if(dr)*dr=0;
    for(;;){
        int i;
        if(k->beg>=k->end){if(!k->eof){k->beg=0;k->end=gzread(k->f,k->buf,KBSZ);if(!k->end){k->eof=1;break;}}else break;}
        if(delim=='\n'){for(i=k->beg;i<k->end;i++)if(k->buf[i]=='\n')break;}
        else{for(i=k->beg;i<k->end;i++)if(isspace(k->buf[i]))break;}
        int64_t need=s->n+(i-k->beg)+2;
        if(need>s->m){s->m=need<8?8:need;s->m=s->m*3/2;s->s=realloc(s->s,s->m);}
        any=1;memcpy(s->s+s->n,k->buf+k->beg,i-k->beg);s->n+=i-k->beg;k->beg=i+1;
        if(i<k->end){if(dr)*dr=k->buf[i];break;}
    }
    if(!s->s){s->m=1;s->s=calloc(1,1);}else if(!any)return -1;
    s->s[s->n]=0;return s->n;
}
static Kseq *kseq_open(gzFile fd){Kseq*s=calloc(1,sizeof*s);s->f=ks_open(fd);return s;}
static void kseq_close(Kseq*s){if(!s)return;free(s->name.s);free(s->comment.s);free(s->seq.s);free(s->qual.s);ks_close(s->f);free(s);}
static int kseq_read(Kseq*s){
    int c;KS*k=s->f;
    if(!s->last){while((c=ks_gc(k))!=-1&&c!='>'&&c!='@');if(c==-1)return -1;s->last=c;}
    s->name.n=s->comment.n=s->seq.n=s->qual.n=0;
    if(ks_getuntil(k,0,&s->name,&c)<0)return -1;
    if(c!='\n')ks_getuntil(k,'\n',&s->comment,0);
    while((c=ks_gc(k))!=-1&&c!='>'&&c!='+'&&c!='@'){
        if(c=='\n')continue;
        if(s->seq.n+1>=(int64_t)s->seq.m){s->seq.m=s->seq.m<16?32:s->seq.m*2;s->seq.s=realloc(s->seq.s,s->seq.m);}
        s->seq.s[s->seq.n++]=c;
        ks_getuntil(k,'\n',&s->seq,0);
    }
    if(s->seq.n+1>=(int64_t)s->seq.m){s->seq.m=s->seq.n+2;s->seq.s=realloc(s->seq.s,s->seq.m);}
    s->seq.s[s->seq.n]=0;
    if(c=='>'||c=='@'){s->last=c;return s->seq.n;}
    if(c=='+'){
        s->last=0;
        if(s->qual.m<s->seq.m){s->qual.m=s->seq.m;s->qual.s=realloc(s->qual.s,s->qual.m);}
