    for(i=0;i<=maxpos;i++){
        long long cnt=pcnt[i];if(cnt==0)continue;
        double ep_avg=pq[i]/cnt;
        double errq=ep_avg>0?-10.0*log10(ep_avg):99.0;
        double avgq=pqs[i]/cnt;
        double pA=100.0*pa[i]/cnt,pC=100.0*pc[i]/cnt,pG=100.0*pg[i]/cnt;
        double pT=100.0*pt[i]/cnt,pN=100.0*pn[i]/cnt;
        double plo=100.0*plow[i]/cnt,phi2=100.0*phigh[i]/cnt;
        if(i==0)printf("ALL\t%lld\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\n",
                       cnt,pA,pC,pG,pT,pN,avgq,errq,plo,phi2);
        else printf("%d\t%lld\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\n",
