static void trimfq_mott(const char*qual,int l,double q,int min_l,int*pbeg,int*pend){
    /* Kadane's algorithm to find max-score subarray */
    int best_s=0,best_e=0,start=0,i;
    double max_here=0.0,max_sum=0.0;
    for(i=0;i<l;i++){
        int qi=(uint8_t)qual[i]-33;if(qi<0)qi=0;if(qi>93)qi=93;
        double ep=pow(10.0,-(double)qi/10.0);
