static int stk_split(int argc,char*argv[]){
    int c,nfiles=10,ll=0;
    while((c=getopt(argc,argv,"n:l:"))!=-1){switch(c){case 'n':nfiles=atoi(optarg);break;case 'l':ll=atoi(optarg);break;default:break;}}
    if(argc-optind<2){
        fprintf(stderr,"Usage: seqtk split [options] <prefix> <in.fa>\n");
        fprintf(stderr,"Options:\n  -n INT    number of files [10]\n  -l INT    line length [0]\n");
        return 0;
    }
    char*prefix=argv[optind];
    gzFile fp=xopen(argv[optind+1],"r");
    if(!fp)return 1;
    FILE**fout=calloc(nfiles,sizeof(FILE*));
    int i;
    for(i=0;i<nfiles;i++){
        char fn[4096];sprintf(fn,"%s.%05d.fa",prefix,i+1);
        fout[i]=fopen(fn,"w");
    }
    Kseq*seq=kseq_open(fp);int idx=0;
    while(kseq_read(seq)>=0){
        FILE*f=fout[idx%nfiles];
        fprintf(f,">%s\n",(char*)seq->name.s);
        prnseq(f,(char*)seq->seq.s,(int)seq->seq.n,ll);
