/* ============================================================ trimfq ============================================================ */
static void trimfq_mott(const char*qual,int l,double q,int min_l,int*pbeg,int*pend){
    /* Kadane's algorithm to find max-score subarray */
    int best_s=0,best_e=0,start=0,i;
    double max_here=0.0,max_sum=0.0;
    for(i=0;i<l;i++){
        int qi=(uint8_t)qual[i]-33;if(qi<0)qi=0;if(qi>93)qi=93;
        double ep=pow(10.0,-(double)qi/10.0);
        double sc=q-ep;
        max_here+=sc;
        if(max_here>max_sum){max_sum=max_here;best_e=i+1;best_s=start;}
        if(max_here<0){max_here=0.0;start=i+1;}
    }
    int beg=best_s,end=best_e;
    if(end-beg<min_l&&l>=min_l){
        int needed=min_l-(end-beg);
        int expand_l=needed<beg?needed:beg;
        beg-=expand_l;
        int remain=needed-expand_l;
        if(remain>0){end=(end+remain<l?end+remain:l);}
        int still=min_l-(end-beg);
        if(still>0)beg=beg-still>=0?beg-still:0;
    }
    *pbeg=beg;*pend=end;
}

static int stk_trimfq(int argc,char*argv[]){
    int c,trim_l=0,trim_r=0,trim_L=0,min_l=30,force_fq=0;
    double q=0.05;
    while((c=getopt(argc,argv,"q:l:b:e:L:Q"))!=-1){
        switch(c){case 'q':q=atof(optarg);break;case 'l':min_l=atoi(optarg);break;
                  case 'b':trim_l=atoi(optarg);break;case 'e':trim_r=atoi(optarg);break;
                  case 'L':trim_L=atoi(optarg);break;case 'Q':force_fq=1;break;default:break;}
    }
    if(argc-optind==0){
        fprintf(stderr,"\nUsage:   seqtk trimfq [options] <in.fq>\n\n");
        fprintf(stderr,"Options: -q FLOAT    error rate threshold (disabled by -b/-e) [0.05]\n");
        fprintf(stderr,"         -l INT      maximally trim down to INT bp (disabled by -b/-e) [30]\n");
        fprintf(stderr,"         -b INT      trim INT bp from left (non-zero to disable -q/-l) [0]\n");
        fprintf(stderr,"         -e INT      trim INT bp from right (non-zero to disable -q/-l) [0]\n");
        fprintf(stderr,"         -L INT      retain at most INT bp from the 5'-end (non-zero to disable -q/-l) [0]\n");
        fprintf(stderr,"         -Q          force FASTQ output\n\n");
        return 1;
    }
    gzFile fp=xopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_trimfq] failed to open file.\n");return 1;}
    Kseq*seq=kseq_open(fp);
    while(kseq_read(seq)>=0){
        int l=(int)seq->seq.n;
        char*s=(char*)seq->seq.s,*qstr=seq->qual.n?(char*)seq->qual.s:NULL;
        int beg=0,end=l;
        if(trim_l||trim_r||trim_L){
            if(trim_l){beg=trim_l<l?trim_l:l;}
            if(trim_r){end=l-trim_r>beg?l-trim_r:beg;}
            if(trim_L>0){int ne=beg+trim_L;if(ne<end)end=ne;}
        }else if(qstr){
            trimfq_mott(qstr,l,q,min_l,&beg,&end);
        }
        int sl=end-beg; if(sl<0)sl=0;
        if(qstr||force_fq){
            printf("@%s\n",(char*)seq->name.s);
            prnseq(stdout,s+beg,sl,0);
            printf("+\n");
            if(qstr)prnseq(stdout,qstr+beg,sl,0);
            else{int i;for(i=0;i<sl;i++)putchar('I');putchar('\n');}
        }else{
            printf(">%s\n",(char*)seq->name.s);
            prnseq(stdout,s+beg,sl,0);
        }
    }
    kseq_close(seq);gzclose(fp);return 0;
}
