/* ============================================================ gc ============================================================ */
static int stk_gc(int argc,char*argv[]){
    int c,is_at=0,min_l=20;double min_frac=0.6,xdrop=10.0;
    while((c=getopt(argc,argv,"wf:l:x:"))!=-1){switch(c){case 'w':is_at=1;break;case 'f':min_frac=atof(optarg);break;case 'l':min_l=atoi(optarg);break;case 'x':xdrop=atof(optarg);break;default:fprintf(stderr,"gc: invalid option -- '%c'\n",c);break;}}
    if(argc-optind==0){
        fprintf(stderr,"Usage: seqtk gc [options] <in.fa>\n");
        fprintf(stderr,"Options:\n  -w         identify high-AT regions\n");
        fprintf(stderr,"  -f FLOAT   min GC fraction (or AT fraction for -w) [0.60]\n");
        fprintf(stderr,"  -l INT     min region length to output [20]\n");
        fprintf(stderr,"  -x FLOAT   X-dropoff [10.0]\n");
        return 1;
    }
    gzFile fp=xopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_gc] failed to open the input file/stream.\n");return 1;}
    Kseq*seq=kseq_open(fp);
