        double score=0,max_score=0,min_score=0;
        int beg=-1,max_beg=0,max_end=0;
        for(i=0;i<l;i++){
            int ch=toupper((uint8_t)s[i]);
            double val;
            if(is_at)val=(ch=='A'||ch=='T')?min_frac:-(1.0-min_frac);
