            }
        }
        if(beg>=0&&max_end-beg>=min_l)printf("%s\t%d\t%d\t%d\n",(char*)seq->name.s,beg,max_end,max_end-beg);
    }
    kseq_close(seq);gzclose(fp);return 0;
}

