        fprintf(stderr,"      'chr  1-based-pos  any  base-changed-to'.\n");
        return 0;
    }
    typedef struct{int pos;char base;}SNP;
    typedef struct{char*chr;int n,m;SNP*snps;}SList;
    NH*nm=nh_new();int ns=0,ms=0;SList*sl=NULL;
    FILE*fp2=fopen(argv[optind+1],"r");
    if(!fp2){fprintf(stderr,"[stk_mutfa] failed to open SNP file.\n");return 1;}
    char buf[65536];
    while(fgets(buf,sizeof buf,fp2)){
        char*f[8];int nf=0;char*p=buf;
        while(*p&&nf<8){f[nf++]=p;while(*p&&*p!='\t'&&*p!='\n')p++;if(*p)*p++=0;}
        if(nf<4)continue;
        int idx=nh_put(nm,f[0]);
        while(idx>=ms){int o=ms;ms=ms<4?4:ms*2;sl=realloc(sl,ms*sizeof*sl);memset(sl+o,0,(ms-o)*sizeof*sl);}
        if(idx>=ns){sl[idx].chr=strdup(f[0]);ns=idx+1;}
        if(sl[idx].n>=sl[idx].m){sl[idx].m=sl[idx].m<4?4:sl[idx].m*2;sl[idx].snps=realloc(sl[idx].snps,sl[idx].m*sizeof(SNP));}
        sl[idx].snps[sl[idx].n].pos=atoi(f[1]);
        sl[idx].snps[sl[idx].n].base=toupper((uint8_t)f[3][0]);
        sl[idx].n++;
    }
    fclose(fp2);
    gzFile fp=xopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[stk_mutfa] failed to open FA file.\n");return 1;}
    Kseq*seq=kseq_open(fp);
    while(kseq_read(seq)>=0){
        int idx=nh_get(nm,(char*)seq->name.s);
        if(idx>=0){
            int j;char*s=(char*)seq->seq.s;int l=(int)seq->seq.n;
            for(j=0;j<sl[idx].n;j++){
                int pos=sl[idx].snps[j].pos-1;
                if(pos>=0&&pos<l)s[pos]=sl[idx].snps[j].base;
            }
        }
        printf(">%s\n%s\n",(char*)seq->name.s,(char*)seq->seq.s);
    }
    kseq_close(seq);gzclose(fp);
    int i;for(i=0;i<ns;i++){free(sl[i].chr);free(sl[i].snps);}
    free(sl);nh_free(nm);return 0;
}
