            n1=strdup(nm);s1=strdup((char*)seq->seq.s);
            q1=seq->qual.n?strdup((char*)seq->qual.s):NULL;h1=1;
        }else{
            /* check if they're a pair by base name */
            int l1n=strlen(n1),l2n=strlen(nm);int paired=0;
            if(l1n>2&&n1[l1n-2]=='/'&&l2n>2&&nm[l2n-2]=='/'){
                char t1[4096],t2[4096];
                strncpy(t1,n1,l1n-2);t1[l1n-2]=0;
                strncpy(t2,nm,l2n-2);t2[l2n-2]=0;
                paired=!strcmp(t1,t2);
            }else paired=!strcmp(n1,nm);
            if(paired){
                if(q1)printf("@%s\n%s\n+\n%s\n",n1,s1,q1);else printf(">%s\n%s\n",n1,s1);
                if(seq->qual.n)printf("@%s\n%s\n+\n%s\n",nm,(char*)seq->seq.s,(char*)seq->qual.s);
                else printf(">%s\n%s\n",nm,(char*)seq->seq.s);
                free(n1);free(s1);free(q1);n1=NULL;s1=NULL;q1=NULL;h1=0;
