/* ============================================================ cutN ============================================================ */
static int stk_cutN(int argc,char*argv[]){
    int c,n_size=1000,penalty=10,gaps_only=0;
    while((c=getopt(argc,argv,"n:p:g"))!=-1){
        switch(c){case 'n':n_size=atoi(optarg);break;case 'p':penalty=atoi(optarg);break;case 'g':gaps_only=1;break;default:break;}
    }
    if(argc-optind==0){
        fprintf(stderr,"\nUsage:   seqtk cutN [options] <in.fa>\n\n");
        fprintf(stderr,"Options: -n INT    min size of N tract [1000]\n");
        fprintf(stderr,"         -p INT    penalty for a non-N [10]\n");
        fprintf(stderr,"         -g        print gaps only, no sequence\n\n");
        return 1;
    }
    gzFile fp=xopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_cutN] failed to open the input file/stream.\n");return 1;}
    Kseq*seq=kseq_open(fp);
    while(kseq_read(seq)>=0){
        int l=(int)seq->seq.n;char*s=(char*)seq->seq.s;
        /* Use score-based algorithm to find N tracts */
        int i=0,prev_end=0;
        while(i<l){
            /* Find start of significant N tract */
            int ntstart=-1,nscore=0,j;
            for(j=i;j<l;j++){
                int ch=toupper((uint8_t)s[j]);
                if(ch=='N') nscore++;
                else{
                    nscore-=penalty;
                    if(nscore<0){
                        if(ntstart>=0&&nscore+penalty>=n_size){
                            /* found N tract ending just before this non-N stretch cut it */
                            int ntend=j;
                            /* find actual end of N run */
                            while(ntend>ntstart&&toupper((uint8_t)s[ntend-1])!='N')ntend--;
                            if(gaps_only){
                                printf("%s\t%d\t%d\n",(char*)seq->name.s,ntstart,ntend);
                            }else{
                                int seglen=ntstart-prev_end;
                                if(seglen>0){
                                    printf(">%s:%d-%d\n",(char*)seq->name.s,prev_end+1,ntstart);
                                    prnseq(stdout,s+prev_end,seglen,60);
                                }
                            }
                            prev_end=ntend;i=ntend;ntstart=-1;nscore=0;
                            break;
                        }
                        ntstart=-1;nscore=0;
                    }
                }
                if(ntstart<0&&ch=='N')ntstart=j;
                if(ntstart<0&&ch!='N')ntstart=-1;
            }
            if(j>=l){
                /* Check if trailing N tract at end */
                if(ntstart>=0&&nscore>=n_size){
                    int ntend=l;
                    while(ntend>ntstart&&toupper((uint8_t)s[ntend-1])!='N')ntend--;
                    if(gaps_only)printf("%s\t%d\t%d\n",(char*)seq->name.s,ntstart,ntend);
                    else{
                        int seglen=ntstart-prev_end;
                        if(seglen>0){printf(">%s:%d-%d\n",(char*)seq->name.s,prev_end+1,ntstart);prnseq(stdout,s+prev_end,seglen,60);}
                    }
                    prev_end=ntend;
                }
                break;
            }
        }
        if(!gaps_only){
            int seglen=l-prev_end;
            if(seglen>0){printf(">%s:%d-%d\n",(char*)seq->name.s,prev_end+1,l);prnseq(stdout,s+prev_end,seglen,60);}
        }
    }
    kseq_close(seq);gzclose(fp);return 0;
}
