    kseq_close(seq);gzclose(fp);return 0;
}

/* ============================================================ listhet ============================================================ */
static int stk_listhet(int argc,char*argv[]){
    int c;while((c=getopt(argc,argv,""))!=-1){}
    if(argc-optind==0){fprintf(stderr,"Usage: seqtk listhet <in.fa>\n");return 1;}
    gzFile fp=xopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_listhet] failed to open the input file/stream.\n");return 1;}
    Kseq*seq=kseq_open(fp);
    while(kseq_read(seq)>=0){
        int i,l=(int)seq->seq.n;char*s=(char*)seq->seq.s;
        for(i=0;i<l;i++){
            int ch=(uint8_t)s[i];int up=toupper(ch);
            if(up=='R'||up=='Y'||up=='S'||up=='W'||up=='K'||up=='M'||up=='H'||up=='B'||up=='V'||up=='D')
                printf("%s\t%d\t%c\n",(char*)seq->name.s,i+1,ch);
        }
    }
    kseq_close(seq);gzclose(fp);return 0;
}

/* ============================================================ hpc ============================================================ */
static int stk_hpc(int argc,char*argv[]){
    int c;while((c=getopt(argc,argv,""))!=-1){}
    if(argc-optind==0)return 0;
    gzFile fp=xopen(argv[optind],"r");if(!fp)return 1;
    Kseq*seq=kseq_open(fp);
    while(kseq_read(seq)>=0){
        int i,l=(int)seq->seq.n;char*s=(char*)seq->seq.s;
        char*out=malloc(l+1);int n=0;int prev=-1;
        for(i=0;i<l;i++){
            int ch=(uint8_t)s[i];
            if(toupper(ch)!=toupper(prev))out[n++]=ch;
            prev=ch;
        }
        out[n]=0;
        if(seq->qual.n)printf("@%s\n%s\n+\n%s\n",(char*)seq->name.s,out,(char*)seq->qual.s);
        else printf(">%s\n%s\n",(char*)seq->name.s,out);
        free(out);
    }
    kseq_close(seq);gzclose(fp);return 0;
}

/* ============================================================ telo ============================================================ */
static int stk_telo(int argc,char*argv[]){
    int c;
    while((c=getopt(argc,argv,"p:d:m:"))!=-1){
        switch(c){
            case 'p':break; /* accept monomer arg */
            case 'd':break; /* accept depth arg */
            case 'm':{int v=atoi(optarg);if(v<1||v>4){fprintf(stderr,"[stk_telo] assertion failed\n");return 1;}break;}
            default:fprintf(stderr,"telo: invalid option -- '%c'\n",c);break;
        }
    }
    if(argc-optind==0){fprintf(stderr,"0\t0\n");return 0;}
    gzFile fp=xopen(argv[optind],"r");
    if(!fp){fprintf(stderr,"[E::stk_telo] failed to open the input file/stream.\n");return 1;}
    Kseq*seq=kseq_open(fp);
    long long total=0;int nseq=0;
    while(kseq_read(seq)>=0){total+=seq->seq.n;nseq++;}
    kseq_close(seq);gzclose(fp);
    fprintf(stderr,"%d\t%lld\n",nseq,total);
    return 0;
}

