        fprintf(stderr,"         size      report the number sequences and bases\n");
        fprintf(stderr,"         comp      get the nucleotide composition of FASTA/Q\n");
        fprintf(stderr,"         sample    subsample sequences\n");
        fprintf(stderr,"         subseq    extract subsequences from FASTA/Q\n");
        fprintf(stderr,"         fqchk     fastq QC (base/quality summary)\n");
        fprintf(stderr,"         mergepe   interleave two PE FASTA/Q files\n");
        fprintf(stderr,"         split     split one file into multiple smaller files\n");
        fprintf(stderr,"         trimfq    trim FASTQ using the Phred algorithm\n\n");
        fprintf(stderr,"         hety      regional heterozygosity\n");
        fprintf(stderr,"         gc        identify high- or low-GC regions\n");
        fprintf(stderr,"         mutfa     point mutate FASTA at specified positions\n");
        fprintf(stderr,"         mergefa   merge two FASTA/Q files\n");
        fprintf(stderr,"         famask    apply a X-coded FASTA to a source FASTA\n");
        fprintf(stderr,"         dropse    drop unpaired from interleaved PE FASTA/Q\n");
        fprintf(stderr,"         rename    rename sequence names\n");
        fprintf(stderr,"         randbase  choose a random base from hets\n");
        fprintf(stderr,"         cutN      cut sequence at long N\n");
        fprintf(stderr,"         gap       get the gap locations\n");
        fprintf(stderr,"         listhet   extract the position of each het\n");
        fprintf(stderr,"         hpc       homopolyer-compressed sequence\n");
        fprintf(stderr,"         telo      identify telomere repeats in asm or long reads\n\n");
        return 0;
    }
    if(!strcmp(argv[1],"seq"))return stk_seq(argc-1,argv+1);
    if(!strcmp(argv[1],"size"))return stk_size(argc-1,argv+1);
    if(!strcmp(argv[1],"comp"))return stk_comp(argc-1,argv+1);
    if(!strcmp(argv[1],"sample"))return stk_sample(argc-1,argv+1);
    if(!strcmp(argv[1],"subseq"))return stk_subseq(argc-1,argv+1);
    if(!strcmp(argv[1],"fqchk"))return stk_fqchk(argc-1,argv+1);
    if(!strcmp(argv[1],"mergepe"))return stk_mergepe(argc-1,argv+1);
    if(!strcmp(argv[1],"split"))return stk_split(argc-1,argv+1);
    if(!strcmp(argv[1],"trimfq"))return stk_trimfq(argc-1,argv+1);
    if(!strcmp(argv[1],"hety"))return stk_hety(argc-1,argv+1);
    if(!strcmp(argv[1],"gc"))return stk_gc(argc-1,argv+1);
    if(!strcmp(argv[1],"mutfa"))return stk_mutfa(argc-1,argv+1);
    if(!strcmp(argv[1],"mergefa"))return stk_mergefa(argc-1,argv+1);
    if(!strcmp(argv[1],"famask"))return stk_famask(argc-1,argv+1);
    if(!strcmp(argv[1],"dropse"))return stk_dropse(argc-1,argv+1);
    if(!strcmp(argv[1],"rename"))return stk_rename(argc-1,argv+1);
    if(!strcmp(argv[1],"randbase"))return stk_randbase(argc-1,argv+1);
    if(!strcmp(argv[1],"cutN"))return stk_cutN(argc-1,argv+1);
    if(!strcmp(argv[1],"gap"))return stk_gap(argc-1,argv+1);
    if(!strcmp(argv[1],"listhet"))return stk_listhet(argc-1,argv+1);
    if(!strcmp(argv[1],"hpc"))return stk_hpc(argc-1,argv+1);
    if(!strcmp(argv[1],"telo"))return stk_telo(argc-1,argv+1);
    fprintf(stderr,"[seqtk] unknown command '%s'\n",argv[1]);return 1;
}
